(* ::Section:: *)
(*Protected Namespace for Algebras, Dynkin Labels, and various Tensors*)


(*Naming algerbas and representations*)
Protect[a,b,c,d,e,f,g,
su,so,sp,
ad,F];

(*abstract colour tensors and objects related to amplitudes*)
Protect[amp,trR,trF,trAd,joTensor,ddmTensor,clebschTensor];

(*operators and miscellany*)
Protect[w,wc,plus,times,power,powers,powera];


(* ::Subsubsection::Closed:: *)
(*Backend: Parsing & Protecting Nomenclature for Algebras*)


tools`parseAlgebra[alg_]:=tools`parseAlgebra[alg]=Module[{bits=(Characters@ToString[alg])/.Association[Join[{"S"->Nothing,"s"->Nothing,"U"->"u","O"->"o","P"->"p","A"->"a","B"->"b","C"->"c","D"->"d","E"->"e","F"->"f","G"->"g","["->Nothing,"]"->Nothing,")"->Nothing,"("->Nothing},Thread[Rule[ToString/@Range[0,9],Range[0,9]]]]],typeDat,rnkDat},rnkDat=FromDigits@Cases[bits,_Integer];typeDat=DeleteCases[bits,_Integer];If[rnkDat===0,Which[typeDat==={"f"},f[4],typeDat==={"g"},g[2],True,"?"],(Which[MemberQ[Partition[ToString/@{a,b,c,d},1],typeDat],ToExpression[typeDat[[1]]][rnkDat],typeDat==={"e"}&&3<=rnkDat<=8,e[rnkDat],typeDat==={"f"},ToExpression[typeDat[[1]]][rnkDat],typeDat==={"g"},ToExpression[typeDat[[1]]][rnkDat],typeDat==={"u"},a[rnkDat-1],typeDat==={"p"}&&EvenQ[rnkDat],c[rnkDat/2],typeDat==={"o"}&&OddQ[rnkDat],b[(rnkDat-1)/2],typeDat==={"o"}&&EvenQ[rnkDat],d[rnkDat/2],True,"?"]//.{e[5]->d[5],e[4]->a[4],b[1]->a[1],b[q_Integer]:>If[q<2,"?",b[q]],c[2]->b[2],c[q_Integer]:>If[q<2,"?",c[q]],d[3]->a[3],d[q_Integer]:>If[q<4,"?",d[q]],e[q_Integer]:>If[MemberQ[Range[6,8],q],e[q],"?"],f[q_Integer]:>If[q==4,f[q],"?"],g[q_Integer]:>If[q==2,g[q],"?"]})]];
tools`legalAlgebraTrueQ[alg_]:=Not[tools`parseAlgebra[alg]==="?"];


(* ::Section:: *)
(*General Functions and Utilities*)


(* ::Subsection:: *)
(*General Utility Functions*)


niceTime[timeInSec_]:=If[timeInSec<($TimeUnit/100)||Not[NumericQ[timeInSec]]||Precision[timeInSec]==0,"",Module[{units=Style[#,FontFamily->"Times",FontSize->16,RGBColor[0.05,0.05,0.5]]&/@{"  years","  weeks","  days"," hrs"," min"," sec"," ms"," \[Mu]s"," ns"},choppedTime=(Quotient[Mod[timeInSec,#1],#2]&@@@Partition[{timeInSec 100,31557600,3600*24*7,3600*24,3600,60,1,10^-3,10^-6,10^-9},2,1])},Row[Riffle[Row[Style[#,FontFamily->"Times",FontSize->16]&/@#]&/@DeleteCases[First[Select[Partition[Transpose[{choppedTime,units}],2,1],First[First[#]]>0&,1]],{0,x_}],", "]]]];

byteCount[bytes_]:=If[Head[bytes]===Integer,Module[{chopped,unitRules=Thread[Rule[Range[0,5],Style[#,FontFamily->"Times",FontSize->16,Bold]&/@{"bytes","kB","MB","GB","TB","PB"}]],unit},unit=Floor[Log[Power[10,3],bytes]];chopped=(Round[10bytes/(Power[Power[10,3],unit])]);Row[{Row[{#1,#2,#3,".",#4}]&@@(PadLeft[Style[#,FontFamily->"Times",FontSize->16]&/@IntegerDigits[chopped],4,Style[0,FontFamily->"Times",FontSize->16,GrayLevel[1]]]),(unit/.unitRules)},Spacer[1]]],byteCount[ByteCount[bytes]]];


(* ::Subsection:: *)
(*Combinatorics-Related Functions*)


randomPerm[n_Integer]/;n>=1:=Nest[Join[#,(RandomInteger[{1,n-Length[#]},{1}]/.Thread[Rule[Range[n-Length[#]],Complement[Range[n],#]]])]&,{},n];

shuffle[p_Integer,q_Integer]:=shuffle[p,q]=Which[Min[{p,q}]==0,{Range[Max[{p,q}]]},q==1,(Insert[Range[p],p+1,#]&/@Reverse[Range[p+1]]),p==1,(Insert[Range[q]+1,1,#]&/@Range[q+1]),OrderedQ[{p,q}],Block[{lower=shuffle[p-1,q]+1},DeleteCases[Join@@Transpose[(PadRight[#,p+q,{{}}]&/@(Function[{qList},(Insert[qList,1,#]&/@Range[Ordering[qList][[1]]])]/@lower))],{}]],True,Block[{lower=shuffle[p,q-1]},Join@@Function[{pList},(Insert[pList,p+q,#]&/@Reverse[Range[Ordering[pList][[-1]]+1,p+q]])]/@lower]];
shuffle[a_List,b_List]:=Block[{seeds=(shuffle@@(Length/@{a,b}))},seeds/.Thread[Rule[Range[Length[seeds[[1]]]],Join[a,b]]]];

riordanNumber[n_Integer]/;n>=0:=riordanNumber[n]=Which[n==0,1,n==1,0,True,(n-1)/(n+1) (2riordanNumber[n-1]+3riordanNumber[n-2])];


(* ::Subsection:: *)
(*SparseArray Operations and Utilities*)


(*improved implementation of Mathematica's TensorContract*)
tensorContract[{tensorList__SparseArray},{indexList___List}]:=Activate[TensorContract[Inactive[TensorProduct][tensorList],{indexList}]];
tensorContract[{tensorList__SparseArray},{indexPair__Integer}]:=Activate[TensorContract[Inactive[TensorProduct][tensorList],{{indexPair}}]];
tensorContract[tensor_SparseArray,{indexList___List}]:=If[Length[{indexList}]==0,tensor,Activate[TensorContract[Inactive[TensorProduct][tensor],{indexList}]]];

(*contracting last-with-first slots between SparseArray objects*)
dot[a_SparseArray]:=a;
dot[a_SparseArray,b_SparseArray]:=Module[{lens=Length[Dimensions[#]]&/@{a,b},slots,out},slots=({0,1}+((Total[lens[[1;;#-1]]]+lens[[#]])))&/@Range[Length[{a,b}]-1];out=SparseArray@tensorContract[{a,b},slots];If[Length[Dimensions[a]]==Length[Dimensions[b]]==3&&(Length[DeleteDuplicates[Dimensions[a]]]==1),If[inducedAdjoint[Transpose[b]]===a,(Set[tools`drawTensor[out],tools`fDotTgraphic[Transpose[b]]];Set[tools`drawTensor[Transpose[out,{2,3,1,4}]],tools`fDotTgraphicR[Transpose[b]]];)]];out];
dot[a_SparseArray,b_SparseArray,x__SparseArray]:=Module[{lens=Length[Dimensions[#]]&/@{a,b,x},slots},slots=({0,1}+((Total[lens[[1;;#-1]]]+lens[[#]])))&/@Range[Length[{a,b,x}]-1];SparseArray@tensorContract[{a,b,x},slots]];

(*SparseArray-preserving inverse*)
inverse[array_SparseArray]/;Length[Dimensions[array]]==2&&Length[DeleteDuplicates[Dimensions[array]]]==1:=Module[{out=SparseArray[Inverse[array]]},If[out===array,(out+SparseArray[{1,1}->1,Dimensions[out]]+SparseArray[{1,1}->-1,Dimensions[out]]),out]];
inverse[array_?SquareMatrixQ]:=SparseArray[Inverse[array]];

(*Find linear relations among a list of tensors encoded as SparseArray objects*)
nullSpace[{tensorSequence__SparseArray}]:=Module[{proj,t0=AbsoluteTime[]},proj=Catch[Transpose[Dot@@(NestWhile[Function[{newList,projList},Module[{fRule=ArrayRules[newList[[1]]][[-1]],rules=Association[ArrayRules[#]]&/@newList,slots=ArrayRules[#][[1,1]]&/@newList,newNull},newNull=NullSpace[Transpose[Replace[(slots/.rules),fRule,{2}]]];If[newNull==={},Throw[{}],{SparseArray[SparseArray[newNull] . SparseArray[newList]],Append[projList,Transpose@newNull]}]]]@@#&,{{tensorSequence},{}},Length[ArrayRules[#[[1]]]]>1&][[-1]])]];If[AbsoluteTime[]-t0>1,Print["  nullSpace required ",niceTime[AbsoluteTime[]-t0]," to complete."]];If[proj==={},{},SparseArray@proj]];
nullSpace[q_?MatrixQ]:=SparseArray@NullSpace[q];

(*constructing similarity transforms between representations*)
findSimilarity[rep_SparseArray,repPrime_SparseArray]/;Dimensions[rep]===Dimensions[repPrime]:=Module[{coLists=Normal/@representationRoots/@{rep,repPrime},eqns,solnVars,soln,scale=1,basicChange,d=Dimensions[rep][[1]]},basicChange=If[Not[SameQ@@Dimensions/@coLists]||Not[Sort[Normal[coLists[[1]]]]===Sort[Normal[coLists[[2]]]]],SparseArray[{x_,y_}:>c[x,y],{d,d}],SparseArray[Function[{slot},SparseArray[#->c[slot,#]&/@Flatten[Position[coLists[[2]],coLists[[1,slot]]]],{d}]]/@Range[d]]];eqns=ArrayRules[SparseArray[rep . basicChange-basicChange . repPrime]][[1;;-2,2]];soln=Solve[eqns==0];If[Length[soln]==0,{},(soln=DeleteCases[List@@@First[soln],{x_,0}];solnVars=Variables[soln[[All,2]]];If[Length[solnVars]==1,scale=Sign[Sort[Prepend[DeleteCases[(soln/.solnVars[[1]]->1),{x_,0}],{solnVars[[1,1]],1}]][[1,-1]]](LCM@@(1/Abs[DeleteCases[(soln[[All,2]]/.solnVars[[1]]->1),0]]));];SparseArray[Rule[List@@#1,scale #2]&@@@(Join[Transpose[{solnVars,ReplacePart[(c/@Range[Length[solnVars]]),{-1->1}]}],(soln/.(Thread[Rule[#,ReplacePart[(c/@Range[Length[solnVars]]),{-1->1}]]]&@solnVars))])])]];


(* ::Subsubsection::Closed:: *)
(*Backend: Row-Reduction, Linear Algebra, and General SparseArray Operations*)


tools`independentRows[array_SparseArray,projectorQ_:True]:=Module[{rules=List@@@ArrayRules[array],dim=Dimensions[array][[1]],rowDat,indep,iter,null,target=If[TrueQ[projectorQ],Tr[array],Length[First[array]]],evolving},rowDat=GatherBy[rules,First[#][[1]]&];indep=rowDat[[1,1,1,{1}]];For[iter=1,iter<target,iter++,(null={#[[All,1,2]],#[[All,2]]/#[[1,2]]}&@(rowDat[[1]]);rowDat=DeleteCases[(Function[{row},If[Not[MemberQ[row[[All,1,2]],null[[1,1]]]],row,DeleteCases[{{row[[1,1,1]],#[[1,1]]},Total[#[[All,2]]]}&/@GatherBy[Join[Transpose[{row[[All,1,2]],row[[All,2]]}],{#1,-#2((null[[1,1]]/.Association[Thread[Rule[row[[All,1,2]],row[[All,2]]]]]))}&@@@Transpose[null]],First],{x_,0}]]]/@rowDat[[2;;-1]]),{},{1}];indep=Append[indep,rowDat[[1,1,1,1]]];)];indep];
tools`cleanNumber[number_]:=If[LeafCount[number]<=5,number,Module[{nNum={Re[#],Im[#]}&@Chop[Quiet[N[number,500]],Power[10,-400]],test},test=Sign[nNum[[1]]]Power[Rationalize[Power[nNum[[1]],2],Power[10,-400]],1/2]+I Sign[nNum[[2]]]Power[Rationalize[Power[nNum[[2]],2],Power[10,-400]],1/2];If[Chop[Quiet[N[number-test,5000]],Power[10,-4000]]===0,test,number]]];
tools`cleanArray[array_SparseArray]:=Module[{rules=List@@@ArrayRules[SparseArray[array]][[1;;-2]],targets0,nRules,grps,grps2,newRules,vars},vars=Rule@@@Select[List@@@rules,Length[Variables@#[[2]]]>0&];targets0=Select[DeleteCases[DeleteDuplicates[rules[[All,2]]],0],Length[Variables@#]==0&];grps=({#1,Cases[rules,{x_,#1}][[All,1]]}&)/@targets0;targets0=Chop[Quiet[N[grps[[All,1]],5000]],1/10^4000];grps2=DeleteDuplicates[targets0]/.PositionIndex[Association[Thread[Rule[Range[Length[targets0]],targets0]]]];newRules=Join@@Function[{grp},Module[{eph=FullSimplify[tools`cleanNumber[Sort[grp[[All,1]],LeafCount[#1]<=LeafCount[#2]&][[1]]]]},(#1->eph&)/@Join@@grp[[All,2]]]]/@(grps[[#1]]&)/@grps2;SparseArray[Join[vars,newRules],Dimensions[array]]];

tools`multiplicityGather[list_List]:=Module[{assoc=Association[Thread[Rule[Range[Length[list]],list]]]},Reverse/@List@@@Normal[Counts[assoc]]];


(* ::Section:: *)
(*Stylized Summary Tables & Other Information*)


(* ::Subsection:: *)
(*Displaying the Generators of a Concrete Representation*)


showGenerators[rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]:=Module[{generators=Transpose[rep],labels=(-representationRoots[adjointRep[representationAlgebra[rep]]] . cartan[representationAlgebra[rep]])},labels=ReplacePart[Row[Style[#,FontFamily->"Times",FontSize->14]&/@{"\[Alpha][",Sequence@@(Normal[#]/.q_Integer:>If[q<0,OverBar[-q],q]),"]"}]&/@(Normal@labels),Thread[Rule[#+(Dimensions[rep][[2]]-representationAlgebra[rep][[1]])/2,Subscript[Style[\[GothicH],FontFamily->"Times",FontSize->16],Style[#,FontSize->12,FontFamily->"Times"]]&/@#]&@Range[representationAlgebra[rep][[1]]]]];Column[{nice[#2],#1},Alignment->Center]&@@@Transpose[{labels,generators}]];
showGenerators[h,rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]:=Module[{generators=Transpose[cartanGenerators@rep],labels},labels=Subscript[Style[\[GothicH],FontFamily->"Times",FontSize->16],Style[#,FontSize->12,FontFamily->"Times"]]&/@Range[Length[generators]];Column[{nice[#2],#1},Alignment->Center]&@@@Transpose[{labels,Normal/@generators}]];
showGenerators[e,rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]:=Module[{rnk=representationAlgebra[rep][[1]],labels,dim=Dimensions[rep][[2]]},showGenerators[rep][[-(dim-rnk)/2;;-1]]];
showGenerators[f,rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]:=Module[{rnk=representationAlgebra[rep][[1]],labels,dim=Dimensions[rep][[2]]},showGenerators[rep][[1;;(dim-rnk)/2]]];


(* ::Subsection:: *)
(*Dynkin Diagrams and Root-Systems of Simple Lie Algebras*)


dynkinDiagram[alg_Symbol[k_Integer]]/;tools`legalAlgebraTrueQ[alg[k]]:=Module[{algebra=tools`parseAlgebra[alg[k]],rnk,nodes,edges,labels,head},rnk=algebra[[1]];head=Head[algebra];{nodes,edges}=Which[head===a,{tools`dynkinDiagramNode[1][{#,0}]&/@(Range[rnk]),{tools`dynkinDiagramLine[1][{{1,0},{rnk,0}}]}},head===b,{Append[tools`dynkinDiagramNode[1][{#,0}]&/@(Range[rnk-1]),tools`dynkinDiagramNode[-1][{rnk,0}]],{tools`dynkinDiagramLine[1][{{1,0},{rnk-1,0}}],tools`dynkinDiagramLine[2][{{rnk-1,0},{rnk,0}}]}},head===c,{Append[tools`dynkinDiagramNode[-1][{#,0}]&/@(Range[rnk-1]),tools`dynkinDiagramNode[1][{rnk,0}]],{tools`dynkinDiagramLine[1][{{1,0},{rnk-1,0}}],tools`dynkinDiagramLine[2][{{rnk-1,0},{rnk,0}}]}},head===d,{Append[tools`dynkinDiagramNode[1][{#,0}]&/@(Range[rnk-1]),tools`dynkinDiagramNode[2][{rnk-2,1}]],{tools`dynkinDiagramLine[1][{{1,0},{rnk-1,0}}],tools`dynkinDiagramLine[1][{{rnk-2,0},{rnk-2,1}}]}},head===e,{Append[tools`dynkinDiagramNode[1][{#,0}]&/@(Range[rnk-1]),tools`dynkinDiagramNode[3][{rnk-3,1}]],{tools`dynkinDiagramLine[1][{{1,0},{rnk-1,0}}],tools`dynkinDiagramLine[1][{{rnk-3,0},{rnk-3,1}}]}},head===f,{Join[tools`dynkinDiagramNode[-1][{#,0}]&/@Range[2],tools`dynkinDiagramNode[1][{#+2,0}]&/@Range[2]],{tools`dynkinDiagramLine[1][{{1,0},{2,0}}],tools`dynkinDiagramLine[1][{{3,0},{4,0}}],tools`dynkinDiagramLine[2][{{2,0},{3,0}}]}},head===g,{{tools`dynkinDiagramNode[-1][{1,0}],tools`dynkinDiagramNode[1][{2,0}]},{tools`dynkinDiagramLine[3][{{1,0},{2,0}}]}}];Graphics[Join[edges,nodes],ImageSize->40k]];

showLatticeData[alg_Symbol[k_Integer]]/;tools`legalAlgebraTrueQ[alg[k]]:=Module[{algebra=tools`parseAlgebra[alg[k]],cart,diagram,theta,dim,metric},cart=cartan[algebra];diagram=dynkinDiagram[algebra];theta=adjointDynkinLabel[algebra];dim=representationDimension[theta];metric=weightMetric[algebra];Grid[{{Row[{nice[algebra],Style[": ",FontFamily->"Times",FontSize->20]}],Style["Dynkin Diagram",FontFamily->"Times",FontSize->20,Bold],Style["   Cartan Matrix   ",FontFamily->"Times",FontSize->20,Bold],Style["   Weight Metric   ",FontFamily->"Times",FontSize->20,Bold]},{"",Column[{diagram,Row[{Row[{Style["w",FontFamily->"Times",Italic,FontSize->20],Style["(",FontFamily->"Times",FontSize->20],Style["ad",FontFamily->"Times",RGBColor[0.6,0.2,0.3],FontSize->20,Bold],Style[")",FontFamily->"Times",FontSize->20]}],Style[" ",FontSize->3],Style[":=",FontFamily->"Times",FontSize->20],Row[Style[#,FontFamily->"Times",FontSize->18]&/@{"[",Sequence@@List@@theta,"]     "}]}],Row[{Row[{Style["w",FontFamily->"Times",Italic,FontSize->20],Style["(",FontFamily->"Times",FontSize->20],Style["F",FontFamily->"Times",RGBColor[0.2,0.2,0.6],FontSize->20,Bold],Style[")",FontFamily->"Times",FontSize->20]}],Style["  :=",FontFamily->"Times",FontSize->20],Row[Style[#,FontFamily->"Times",FontSize->18]&/@{"[",Sequence@@PadRight[{1},algebra[[1]]],"]     "}]}],Which[Head[algebra]===b,Row[{Row[{Style["w",FontFamily->"Times",Italic,FontSize->20],Style["(",FontFamily->"Times",FontSize->20],Style["S",FontFamily->"Times",RGBColor[0.2,0.5,0.2],FontSize->20,Bold],Style[")",FontFamily->"Times",FontSize->20]}],Style[" ",FontSize->3],Style[" ",FontFamily->"Times",FontSize->18],Style[" :=",FontFamily->"Times",FontSize->20],Row[Style[#,FontFamily->"Times",FontSize->18]&/@{"[",Sequence@@(PadLeft[{1},First[algebra]]),"]     "}]}],Head[algebra]===d,Sequence@@{Row[{Row[{Style["w",FontFamily->"Times",Italic,FontSize->20],Style["(",FontFamily->"Times",FontSize->20],Style["\!\(\*SubscriptBox[\(S\), \(1\)]\)",FontFamily->"Times",RGBColor[0.2,0.5,0.2],FontSize->20,Bold],Style[")",FontFamily->"Times",FontSize->20]}],Style[" :=",FontFamily->"Times",FontSize->20],Row[Style[#,FontFamily->"Times",FontSize->18]&/@{"[",Sequence@@(PadLeft[{1},First[algebra]]),"]     "}]}],Row[{Row[{Style["w",FontFamily->"Times",Italic,FontSize->20],Style["(",FontFamily->"Times",FontSize->20],Style["\!\(\*SubscriptBox[\(S\), \(2\)]\)",FontFamily->"Times",RGBColor[0.2,0.5,0.2],FontSize->20,Bold],Style[")",FontFamily->"Times",FontSize->20]}],Style[" :=",FontFamily->"Times",FontSize->20],Row[Style[#,FontFamily->"Times",FontSize->18]&/@{"[",Sequence@@(PadLeft[{1,0},First[algebra]]),"]     "}]}]},True,Nothing]}],nice[cart],nice[metric]}},Alignment->{Center,Top}]];


(* ::Subsection:: *)
(*Weight Systems/Lattices for Simple Lie Algebras and their Irreducible Representations*)


showWeightLattice[w[alg_Symbol][weight__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{weight}]]]:=Module[{spindleDat={tools`highestWeightSpindle[w[alg][weight]]}},spindleDat=(Join@@Function[{mult,wt},wt&/@Range[mult]]@@@#)&/@#&/@spindleDat;(Column[Row/@#,Alignment->Center]&/@(Row[{"(",(##),")"}]&@@@#&/@#&/@(spindleDat/.q_Integer:>If[q<0,Style[OverBar[-q],FontFamily->"Times",tools`numberColour[q]],Style[q,FontFamily->"Times",tools`numberColour[q]]])))[[1]]];
showWeightLattice[alg_Symbol[rank_Integer]]/;tools`legalAlgebraTrueQ[alg[rank]]:=showWeightLattice[adjointDynkinLabel[tools`parseAlgebra[alg[rank]]]];
showWeightLattice[F[alg_Symbol[rank_Integer]]]/;tools`legalAlgebraTrueQ[alg[rank]]:=(showWeightLattice[w[Head[tools`parseAlgebra[alg[rank]]]]@@PadRight[{1},First[tools`parseAlgebra[alg[rank]]]]]);
showWeightLattice[plus[args__times]]:=Module[{parts=Join@@(Function[{m,w},showWeightLattice[w]&/@Range[m]]@@@{args})},parts];showWeightLattice[times[m_,w_]]:=Row@(showWeightLattice[w]&/@Range[m]);
showWeightLattice[power[w[alg_][label__Integer],n_Integer],expandedQ_:False]:=Module[{weights,cartI=inverse[cartan[alg[Length[{label}]]]]},weights={GatherBy[Normal[representationWeights[power[w[alg][label],n]]],Total[# . cartI]&]};(Column[Row/@#,Alignment->Center]&/@(Row[{"(",(##),")"}]&@@@#&/@#&/@(weights/.q_?NumericQ:>If[q<0,Style[OverBar[-q],FontFamily->"Times",tools`numberColour[q]],Style[q,FontFamily->"Times",tools`numberColour[q]]])))[[1]]];

showRootLattice[w[alg_Symbol][weight__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{weight}]]]:=Module[{spindleDat={tools`highestWeightSpindle[w[alg][weight]]},cart=inverse[cartan[alg[Length[{weight}]]]]},spindleDat=(Join@@Function[{mult,wt},wt . cart&/@Range[mult]]@@@#)&/@#&/@spindleDat;(Column[Row/@#,Alignment->Center]&/@(Row[{"(",(##),")"}]&@@@#&/@#&/@(spindleDat/.q_?NumericQ:>If[q<0,Style[OverBar[-q],FontFamily->"Times",tools`numberColour[q]],Style[q,FontFamily->"Times",tools`numberColour[q]]])))[[1]]];
showRootLattice[alg_Symbol[rank_Integer]]/;tools`legalAlgebraTrueQ[alg[rank]]:=showRootLattice[adjointDynkinLabel[tools`parseAlgebra[alg[rank]]]];
showRootLattice[F[alg_Symbol[rank_Integer]]]/;tools`legalAlgebraTrueQ[alg[rank]]:=(showRootLattice[w[Head[tools`parseAlgebra[alg[rank]]]]@@PadRight[{1},First[tools`parseAlgebra[alg[rank]]]]]);
showRootLattice[plus[args__times]]:=Module[{parts=Join@@(Function[{m,w},showRootLattice[w]&/@Range[m]]@@@{args})},parts];showRootLattice[times[m_,w_]]:=Row@(showRootLattice[w]&/@Range[m]);
showRootLattice[power[w[alg_][label__Integer],n_Integer],expandedQ_:False]:=Module[{roots={GatherBy[Normal[representationRoots[power[w[alg][label],n]]],Total[#]&]}},(Column[Row/@#,Alignment->Center]&/@(Row[{"(",(##),")"}]&@@@#&/@#&/@(roots/.q_?NumericQ:>If[q<0,Style[OverBar[-q],FontFamily->"Times",tools`numberColour[q]],Style[q,FontFamily->"Times",tools`numberColour[q]]])))[[1]]];


(* ::Subsection:: *)
(*Summary of Irreducible Representations of Fundamental Weight*)


showFundamentalIrrepLabels[type_Symbol[k_Integer]]/;tools`legalAlgebraTrueQ[type[k]]:=Module[{alg=tools`parseAlgebra[type[k]]},Module[{fundamentalWeights=w[Head[alg]]@@@IdentityMatrix[First[alg]]},Column[{nice[alg],Style["Dynkin Labels for Fundamental Irreps",FontFamily->"Times",FontSize->14],Grid[Append[Prepend[Transpose[{(ReplacePart[(fundamentalWeights),1->If[alg===e[8],Row[{Style["ad",FontFamily->"Times",tools`repColour[adjointDynkinLabel[alg]],FontSize->16,Bold],Style["=",FontSize->16],Style["F",FontFamily->"Times",RGBColor[0.2,0.2,0.5],FontSize->16,Bold],Style[":",FontSize->16]}],Row[{Style["F",FontFamily->"Times",RGBColor[0.2,0.2,0.5],FontSize->16,Bold],Style[":",FontSize->16]}]]]/.{adjointDynkinLabel[alg]->Row[{Style["ad",FontFamily->"Times",tools`repColour[adjointDynkinLabel[alg]],FontSize->16,Bold],Style[":",FontSize->16]}],Which[Head[alg]===e,conjugateRep[w[e]@@PadRight[{1},First[alg]]]->Row[{Style[OverBar["F"],FontFamily->"Times",tools`repColour[w[e]@@PadRight[{1},First[alg]]],FontSize->16,Bold],Style[":",FontSize->16]}],Head[alg]===a,w[a]@@PadLeft[{1},First[alg]]->Row[{Style[OverBar["F"],FontFamily->"Times",tools`repColour[w[a]@@PadLeft[{0,1},First[alg]]],FontSize->16,Bold],Style[":",FontSize->16]}],Head[alg]===b,w[b]@@PadLeft[{1},First[alg]]->Row[{Style["S",FontFamily->"Times",tools`repColour[w[b]@@PadLeft[{0,1},First[alg]]],FontSize->16,Bold],Style[":",FontSize->16]}],Head[alg]===d,Sequence@@{w[d]@@PadLeft[{1,0},First[alg]]->Row[{Style["\!\(\*SubscriptBox[\(S\), \(2\)]\)",FontFamily->"Times",tools`repColour[w[d]@@PadLeft[{1,0},First[alg]]],FontSize->16,Bold],Style[":",FontSize->16]}],w[d]@@PadLeft[{1},First[alg]]->Row[{Style["\!\(\*SubscriptBox[\(S\), \(1\)]\)",FontFamily->"Times",tools`repColour[w[d]@@PadLeft[{1,0},First[alg]]],FontSize->16,Bold],Style[":",FontSize->16]}]},True,Nothing],w[q_][x__]:>""}),fundamentalWeights,(fundamentalWeights/.{w[alg_][weight__]:>Which[w[alg][weight]===adjointDynkinLabel[alg[Length[{weight}]]],Tooltip[Style[representationDimension[w[alg][weight]],Bold,FontSize->18,FontFamily->"Times",tools`repColour[w[alg][weight]]],Style[Row[{"[",weight,"]"}],FontFamily->"Times",FontSize->18]],{weight}[[1]]===1&&DeleteCases[DeleteDuplicates[{weight}[[2;;-1]]],0]=={},Tooltip[Style[representationDimension[w[alg][weight]],Bold,FontSize->18,FontFamily->"Times",tools`repColour[w[alg][weight]]],Style[Row[{"[",weight,"]"}],FontFamily->"Times",FontSize->18]],w[alg][weight]===conjugateRep[w[alg]@@PadRight[{1},Length[{weight}]]],Tooltip[Style[OverBar[representationDimension[w[alg][weight]]],Bold,FontSize->18,FontFamily->"Times",tools`repColour[w[alg][weight]]],Style[Row[{"[",weight,"]"}],FontFamily->"Times",FontSize->18]],True,Tooltip[Style[representationDimension[w[alg][weight]],Bold,FontSize->18,FontFamily->"Times",tools`repColour[w[alg][weight]]],Style[Row[{"[",weight,"]"}],FontFamily->"Times",FontSize->18]]]})}],Style[#,FontFamily->"Times",FontSize->14,Bold]&/@{"","Dynkin label","dim"}],Style[#,FontFamily->"Times",FontSize->14,Bold]&/@{"","",""}],Alignment->{{Right,Left,Left}}]},Alignment->Center]]];


(* ::Subsection:: *)
(*Weight Systems of Concrete Representations*)


showWeightLattice[rep_SparseArray,breakDownQ_:False]:=If[TrueQ[breakDownQ],Module[{spindleDat=Reverse@tools`representationSpindles[rep]},spindleDat=(Join@@Function[{mult,weight},weight&/@Range[mult]]@@@#)&/@#&/@spindleDat;Column[Row/@#,Alignment->Center]&/@(Row[{"(",##,")"}]&@@@#&/@#&/@(spindleDat/.q_Integer:>If[q<0,Style[OverBar[-q],FontFamily->"Times",tools`numberColour[q]],Style[q,FontFamily->"Times",tools`numberColour[q]]]))],Module[{spindleDat=(SortBy[#,-#&]&/@GatherBy[Normal[representationRoots[rep]],-Total[#]&]),cart=cartan[representationAlgebra[rep]]},spindleDat=(# . cart&/@#&/@spindleDat);Column[Row/@#,Alignment->Center]&@(Row[{"(",##,")"}]&@@@#&/@(spindleDat/.q_Integer:>If[q<0,Style[OverBar[-q],FontFamily->"Times",tools`numberColour[q]],Style[q,FontFamily->"Times",tools`numberColour[q]]]))]];

showRootLattice[rep_SparseArray,breakDownQ_:False]:=If[TrueQ[breakDownQ],Module[{spindleDat=Reverse@tools`representationSpindles[rep],cart=inverse[cartan[representationAlgebra[rep]]]},spindleDat=(Join@@Function[{mult,weight},weight . cart&/@Range[mult]]@@@#)&/@#&/@spindleDat;Column[Row/@#,Alignment->Center]&/@(Row[{"(",##,")"}]&@@@#&/@#&/@(spindleDat/.q_?NumberQ:>If[q<0,Style[OverBar[-q],FontFamily->"Times",tools`numberColour[q]],Style[q,FontFamily->"Times",tools`numberColour[q]]]))],Module[{spindleDat=(SortBy[#,-#&]&/@GatherBy[Normal[representationRoots[rep]],-Total[#]&])},spindleDat=(#&/@#&/@spindleDat);Column[Row/@#,Alignment->Center]&@(Row[{"(",##,")"}]&@@@#&/@(spindleDat/.q_?NumberQ:>If[q<0,Style[OverBar[-q],FontFamily->"Times",tools`numberColour[q]],Style[q,FontFamily->"Times",tools`numberColour[q]]]))]];


