(* ::Section:: *)
(*Lie Algebra Root Systems and Conventions*)


(* ::Subsection:: *)
(*Dynkin-Labels for Irreducible Representations of Simple Lie Algebras*)


adjointDynkinLabel[algebra_]/;tools`legalAlgebraTrueQ[algebra]:=adjointDynkinLabel[algebra]=w[Head[tools`parseAlgebra[algebra]]]@@Normal[cartanGenerators[adjointRep[algebra]][[1,All,1]] . cartan[algebra]];


(* ::Subsection:: *)
(*Root-Systems for Simple Lie Algebras*)


cartan[alg_]/;tools`legalAlgebraTrueQ[alg]:=If[True,(Set[cartan[alg],#]),#]&@Module[{cartanMetric=repTrace[cartanGenerators[adjointRep[alg]],2,False],invMetric},invMetric=inverse[cartanMetric];invMetric . SparseArray[DiagonalMatrix[(2/Normal@Diagonal[invMetric])]]];

weightMetric[alg_Symbol[k_Integer]]/;tools`legalAlgebraTrueQ[alg[k]]:=If[True,Set[weightMetric[alg[k]],#],#]&@Module[{cart=repTrace[cartanGenerators[fundamentalRep[tools`parseAlgebra[alg[k]]]],2,False]},(1/(2Max[#])DiagonalMatrix[#]) . cart . ((DiagonalMatrix[#]))&@Diagonal[inverse@cart]];


coxeter[alg_Symbol[k_Integer]]/;tools`legalAlgebraTrueQ[alg[k]]:=If[True,Set[coxeter[alg[k]],#],#]&@Module[{rnk=tools`parseAlgebra[alg[k]][[1]]},Total[First[representationRoots[adjointRep[alg[k]]]]]+1];

dualCoxeter[alg_Symbol[k_Integer]]/;tools`legalAlgebraTrueQ[alg[k]]:=dualCoxeter[alg[k]]=Module[{algebra=tools`parseAlgebra[alg[k]]},Module[{met=weightMetric[algebra],cart=cartan[algebra]},Tr[(First[representationRoots[adjointRep@algebra]]) . cart . met]+1]];


positiveRoots[alg_Symbol[k_Integer]]/;tools`legalAlgebraTrueQ[alg[k]]:=Module[{adj,algebra=tools`parseAlgebra[alg[k]]},adj=adjointRep[algebra];representationRoots[adj][[1;;(Dimensions[adj][[1]]-algebra[[1]])/2]]];

positiveWeights[alg_Symbol[k_Integer]]/;tools`legalAlgebraTrueQ[alg[k]]:=Module[{adj,algebra=tools`parseAlgebra[alg[k]]},positiveRoots[algebra] . cartan[algebra]];


(* ::Section:: *)
(*Abstract Analysis of Representations in Terms of Dynkin Labels for Irreducible Representations*)


(* ::Subsection:: *)
(*Operations on Representations' Dynkin Labels*)


conjugateRep[w[alg_Symbol][weight__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{weight}]]]:=(Module[{algebra=alg[Length[{weight}]],rank=Length[{weight}]},w[alg]@@Which[MemberQ[{b,c,f,g},alg],{weight},alg===a,Reverse[{weight}],alg===d,If[EvenQ[rank],{weight},Join[{weight}[[1;;-3]],Reverse[{weight}[[-2;;-1]]]]],alg===e,If[rank>6,{weight},Join[Reverse[{weight}[[1;;5]]],{weight}[[{-1}]]]]]]);
conjugateRep[dynkinLabel_]/;Count[dynkinLabel,w[_][__]|F[a_Symbol[k_Integer]]|ad[alg_Symbol[r_Integer]],{0,\[Infinity]}]>0:=(dynkinLabel/.{F[a_[k_]]:>(w[Head[tools`parseAlgebra[a[k]]]]@@(PadRight[{1},(tools`parseAlgebra[a[k]])[[1]]])),ad[a_[k_]]:>adjointDynkinLabel[tools`parseAlgebra[a[k]]]}/.{w[alg_][labels__]:>conjugateRep[w[alg][labels]]});


(* ::Subsection:: *)
(*Assessment of Irreducible Representations via their Dynkin Labels*)


realRepresentationQ[w[alg_Symbol][weight__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{weight}]]]:=conjugateRep[w[alg][weight]]===w[alg][weight];

pseudoRealRepresentationQ[w[alg_Symbol][weight__Integer]]:=If[TrueQ[realRepresentationQ[w[alg][weight]]],Module[{algebra=alg[Length[{weight}]]},Not[IntegerQ@({weight} . weightMetric[algebra] . Which[alg===g,{3,1},alg===f,{2,2,1,1},alg===b,PadRight[{1},Length[{weight}],2],alg===c,PadLeft[{1},Length[{weight}],2],True,PadRight[{},Length[{weight}],1]])]],False];


casimirEigenvalue[w[alg_Symbol][weight__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{weight}]]]:=casimirEigenvalue[w[alg][weight]]=Module[{metric=repTrace[cartanGenerators[fundamentalRep[alg[Length[{weight}]]]],2,False]},metric=DiagonalMatrix[Diagonal[Inverse[metric]]/2] . metric . DiagonalMatrix[Diagonal[Inverse[metric]]/2];({weight} . metric . ( {weight}+2))];

dynkinIndex[w[alg_Symbol][weight__Integer]]:=casimirEigenvalue[w[alg][weight]]*representationDimension[w[alg][weight]]/representationDimension[adjointDynkinLabel[alg[Length[{weight}]]]];


representationDimension[head_[highestWeight__Integer]]/;tools`legalAlgebraTrueQ[First[head][Length[{highestWeight}]]]:=(representationDimension[head[highestWeight]]=Module[{algebra=tools`parseAlgebra[First[head][Length[{highestWeight}]]]},Product[({highestWeight}+1) . wt/Total[wt],{wt,Transpose[weightMetric[algebra] . Transpose[(positiveRoots[algebra] . cartan[algebra])]]}]]);
representationDimension[times[mult_Integer,head_[weight__Integer]]]:=mult*(representationDimension[head[weight]]);
representationDimension[power[head_[weight__Integer],q_Integer]]:=Power[representationDimension[head[weight]],q];
representationDimension[plus[q___]]:=Total[representationDimension[#]&/@{q}];
representationDimension[ad[type_[k_Integer]]]/;tools`legalAlgebraTrueQ[type[k]]:=representationDimension[adjointDynkinLabel[tools`parseAlgebra[type[k]]]];representationDimension[ad[w[type_Symbol][weightLabel__Integer]]]/;tools`legalAlgebraTrueQ[type[Length[{weightLabel}]]]:=representationDimension[adjointDynkinLabel[tools`parseAlgebra[type[Length[{weightLabel}]]]]];
representationDimension[F[type_[k_Integer]]]/;tools`legalAlgebraTrueQ[type[k]]:=representationDimension[w[#1]@@PadRight[{1},#2]&@@(tools`parseAlgebra[type[k]])];


(*identifying all irreps of a given dimension*)
irrepDimensionToDynkinLabels[type_Symbol[rnk_Integer]][dim_Integer]/;tools`legalAlgebraTrueQ[type[rnk]]:=irrepDimensionToDynkinLabels[type[rnk]][dim]=w[type]@@@If[dim===1,{0&/@Range[rnk]},FixedPoint[Function[{list},DeleteDuplicates[Join@@(Function[{wt},Which[representationDimension[w[type]@@wt]==dim,{wt},representationDimension[w[type]@@wt]<dim,Select[wt+#&/@IdentityMatrix[rnk],representationDimension[w[type]@@#]<=dim&],True,{}]]/@list)]],IdentityMatrix[rnk]]];


(* ::Subsection:: *)
(*Weight-Systems of Irreducible Representations*)


representationWeights[w[alg_Symbol][dynkinLabel__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{dynkinLabel}]]]:=representationWeights[w[alg][dynkinLabel]]=Module[{weights=SparseArray[(Join@@(Function[{mult,wt},wt&/@Range[mult]]@@@tools`highestWeightLattice[w[alg][dynkinLabel]]))]},weights];
representationWeights[alg_Symbol[rank_Integer]]/;tools`legalAlgebraTrueQ[alg[rank]]:=representationWeights[adjointDynkinLabel[tools`parseAlgebra[alg[rank]]]];
representationWeights[F[alg_Symbol[rank_Integer]]]/;tools`legalAlgebraTrueQ[alg[rank]]:=(representationWeights[w[Head[tools`parseAlgebra[alg[rank]]]]@@PadRight[{1},First[tools`parseAlgebra[alg[rank]]]]]);
representationWeights[power[w[alg_Symbol][label__Integer],n_Integer]]:=Module[{cartI=inverse[cartan[tools`parseAlgebra[alg[Length[{label}]]]]],wts},SparseArray@SortBy[Join@@(Join@@(Function[{m,wt},Normal[representationWeights[wt]]&/@Range[m]]@@@(List@@tensorPowerDecomposition[w[alg][label],n]))),{-Total[# . cartI],-Reverse[# . cartI]}&]];representationWeights[powers[w[alg_Symbol][label__Integer],n_Integer]]:=Module[{cartI=inverse[cartan[tools`parseAlgebra[alg[Length[{label}]]]]],wts},SparseArray@SortBy[Join@@(Join@@(Function[{m,wt},Normal[representationWeights[wt]]&/@Range[m]]@@@(List@@symPowerDecomposition[w[alg][label],n]))),{-Total[# . cartI],-Reverse[# . cartI]}&]];representationWeights[powera[w[alg_Symbol][label__Integer],n_Integer]]:=Module[{cartI=inverse[cartan[tools`parseAlgebra[alg[Length[{label}]]]]],wts},SparseArray@SortBy[Join@@(Join@@(Function[{m,wt},Normal[representationWeights[wt]]&/@Range[m]]@@@(List@@antiSymPowerDecomposition[w[alg][label],n]))),{-Total[# . cartI],-Reverse[# . cartI]}&]];
representationWeights[plus[q___times]]:=Module[{cartI,wts,algebra=Cases[{q},w[r_][s__]:>tools`parseAlgebra[r[Length[{s}]]],{0,\[Infinity]}][[1]]},cartI=inverse[cartan[algebra]];SparseArray@SortBy[Join@@(Join@@(Function[{m,wt},Normal[representationWeights[wt]]&/@Range[m]]@@@({q}))),{-Total[# . cartI],-Reverse[# . cartI]}&]];


representationRoots[w[alg_Symbol][dynkinLabel__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{dynkinLabel}]]]:=representationRoots[w[alg][dynkinLabel]]=Module[{weights=representationWeights[w[alg][dynkinLabel]]},weights . inverse[cartan[alg[Length[{dynkinLabel}]]]]];
representationRoots[alg_Symbol[rank_Integer]]/;tools`legalAlgebraTrueQ[alg[rank]]:=representationRoots[adjointDynkinLabel[tools`parseAlgebra[alg[rank]]]];
representationRoots[F[alg_Symbol[rank_Integer]]]/;tools`legalAlgebraTrueQ[alg[rank]]:=(representationRoots[w[Head[tools`parseAlgebra[alg[rank]]]]@@PadRight[{1},First[tools`parseAlgebra[alg[rank]]]]]);
representationRoots[power[w[alg_Symbol][label__Integer],n_Integer]]:=Module[{weights=representationWeights[power[w[alg][label],n]]},weights . inverse[cartan[alg[Length[{label}]]]]];
representationRoots[plus[q___times]]:=Module[{weights=representationWeights[plus[q]],cartI,algebra=Cases[{q},w[r_][s__]:>tools`parseAlgebra[r[Length[{s}]]],{0,\[Infinity]}][[1]]},cartI=inverse[cartan[algebra]];weights . cartI];


(* ::Subsection:: *)
(*Decomposition of Tensor Products into Irreducible Representations*)


(*tensor products*)
tensorProductDecomposition[w[alg_Symbol][weightA__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{weightA}]]]:=plus[times[1,w[alg][weightA]]];
tensorProductDecomposition[power[w[alg_Symbol][weight__Integer],s_Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{weight}]]]&&s>=0:=Which[s==0,plus[times[1,w[alg]@@PadRight[{},Length[{weight}]]]],s==1,plus[times[1,w[alg][weight]]],s==2,tensorProductDecomposition[w[alg][weight],w[alg][weight]],True,Set[tensorProductDecomposition[power[w[alg][weight],s]],tensorProductDecomposition[tensorProductDecomposition[power[w[alg][weight],s-1]],w[alg][weight]]]];tensorProductDecomposition[power[arg_Symbol[alg_Symbol[k_Integer]],s_Integer]]/;s>=0&&MemberQ[{F,ad},arg]:=If[arg===F,tensorProductDecomposition[power[w[alg]@@PadRight[{1},k],s]],tensorProductDecomposition[power[adjointDynkinLabel[alg[k]],s]]];
tensorProductDecomposition[w[alg_Symbol][weightA__Integer],w[alg_Symbol][weightB__Integer]]/;Length[{weightA}]===Length[{weightB}]&&tools`legalAlgebraTrueQ[alg[Length[{weightA}]]]:=If[Not@OrderedQ[representationDimension/@{w[alg][weightA],w[alg][weightB]}],tensorProductDecomposition[w[alg][weightB],w[alg][weightA]],Set[tensorProductDecomposition[w[alg][weightA],w[alg][weightB]],Module[{algebra,rank=Length[{weightA}],type,cart,shifted,out,aLattice,t0=AbsoluteTime[],t00=AbsoluteTime[]},type=alg;algebra=type[rank];cart=Normal@cartan[algebra];If[DeleteDuplicates[{weightA}]==={0},plus[times[1,w[alg]@@{weightB}]],(aLattice=tools`highestWeightLattice[w[alg][weightA]];out={#1,w[alg]@@#2}&@@@DeleteCases[({Total[#[[All,1]]],#[[1,2]]}&/@GatherBy[tools`weylReflect[#+{0,{weightB}},cart]&/@aLattice,Last]),{0,x_}];out=plus@@(times[#1,#2]&@@@SortBy[out,representationDimension[Last[#]]&]);If[AbsoluteTime[]-t00>1,Print["  Tensor product decomposition of ",Row[{"[",weightA,"]","\[CircleTimes]","[",weightB,"]"}]," required ",niceTime[AbsoluteTime[]-t00]]];out)]]]];
tensorProductDecomposition[q___,F[alg_Symbol[k_Integer]],r___]/;tools`legalAlgebraTrueQ[alg[k]]:=(tensorProductDecomposition[q,w[alg]@@PadRight[{1},k],r]);
tensorProductDecomposition[q___,ad[alg_Symbol[k_Integer]],r___]/;tools`legalAlgebraTrueQ[alg[k]]:=(tensorProductDecomposition[q,adjointDynkinLabel[alg[k]],r]);
tensorProductDecomposition[q___,plus[terms__times],r___]:=Module[{bits=Join@@List@@@(tensorProductDecomposition[q,#,r]&/@{terms})},plus@@SortBy[(times[Total[#[[All,1]]],#[[1,2]]]&/@GatherBy[bits,Last]),representationDimension[Last[List@@#]]&]];
tensorProductDecomposition[q___,times[mult_Integer,w[alg_Symbol][weight__Integer]],r___]:=(tensorProductDecomposition[q,w[alg][weight],r]/.{times[s_,w[alg][wt__Integer]]:>times[s mult,w[alg][wt]]});
tensorProductDecomposition[q___,power[arg_,s_Integer],r___]/;Length[{q,r}]>0:=tensorProductDecomposition[q,tensorProductDecomposition[power[arg,s]],r];
tensorProductDecomposition[r___,w[alg_Symbol][weightA__Integer],s___,w[alg_Symbol][weightB__Integer],t___]/;Length[{r,s,t}]>0:=Module[{argList={w[alg][weightA],w[alg][weightB],r,s,t}},If[DuplicateFreeQ[argList],tensorProductDecomposition[tensorProductDecomposition[w[alg][weightA],w[alg][weightB]],r,s,t],tensorProductDecomposition@@(If[Count[argList,#]>1,power[#,Count[argList,#]],#]&/@DeleteDuplicates[argList])]];

(*tensor powers*)
tensorPowerDecomposition[w[alg_Symbol][weight__Integer],q_Integer]:=tensorProductDecomposition[power[w[alg][weight],q]];
tensorPowerDecomposition[ad[alg_Symbol[k_Integer]],q_Integer]:=tensorProductDecomposition[power[adjointDynkinLabel[alg[k]],q]];
tensorPowerDecomposition[F[alg_Symbol[k_Integer]],q_Integer]:=tensorProductDecomposition[power[w[alg]@@PadRight[{1},k],q]];

symPowerDecomposition[w[alg_][highestWeight__Integer],k_Integer]:=symPowerDecomposition[w[alg][highestWeight],k]=tools`highestWeightLabels[alg][tools`symPowerWeightLattice[w[alg][highestWeight],k]]
symPowerDecomposition[F[alg_],k_Integer]/;tools`legalAlgebraTrueQ[alg]:=symPowerDecomposition[w[Head[tools`parseAlgebra[alg]]]@@PadRight[{1},tools`parseAlgebra[alg][[1]]],k];
symPowerDecomposition[ad[alg_],k_Integer]/;tools`legalAlgebraTrueQ[alg]:=symPowerDecomposition[adjointDynkinLabel[tools`parseAlgebra[alg]],k];
symPowerDecomposition[args_,k_Integer]:=symPowerDecomposition[args,k]=tools`highestWeightLabels[Cases[args,w[alg_][dynkinLabels__Integer]:>alg,{0,\[Infinity]}][[1]]][tools`symPowerWeightLattice[args,k]]

antiSymPowerDecomposition[w[alg_][highestWeight__Integer],k_Integer]/;k<=representationDimension[w[alg][highestWeight]]:=antiSymPowerDecomposition[w[alg][highestWeight],k]=tools`highestWeightLabels[alg][tools`antiSymPowerWeightLattice[w[alg][highestWeight],k]];
antiSymPowerDecomposition[F[alg_],k_Integer]/;tools`legalAlgebraTrueQ[alg]:=antiSymPowerDecomposition[w[Head[tools`parseAlgebra[alg]]]@@PadRight[{1},tools`parseAlgebra[alg][[1]]],k];
antiSymPowerDecomposition[ad[alg_],k_Integer]/;tools`legalAlgebraTrueQ[alg]:=antiSymPowerDecomposition[adjointDynkinLabel[tools`parseAlgebra[alg]],k];
antiSymPowerDecomposition[args_,k_Integer]/;Not[Head[Head[args]]===w]:=antiSymPowerDecomposition[args,k]=tools`highestWeightLabels[Cases[args,w[alg_][dynkinLabels__Integer]:>alg,{0,\[Infinity]}][[1]]][tools`antiSymPowerWeightLattice[args,k]];


(* ::Subsection:: *)
(*Counting the Number of Independent 'Colour' Tensors for Amplitudes Involving Various Irreducible Representations*)


numberOfIndependentColourTensors[states__]:=Module[{parsed,alg=Join[Cases[{states},w[a_Symbol][weights__Integer]:>a[Length[{weights}]],{0,\[Infinity]}],Cases[{states},F[a_Symbol[k_Integer]]:>a[k],{0,\[Infinity]}],Cases[{states},ad[a_Symbol[k_Integer]]:>a[k],{0,\[Infinity]}]],left,right,prod,adj,nAdj,nF,fList,decomp,rules},Which[Length[alg]==0,Print["User must specify the Lie algebra."],Length[DeleteDuplicates[alg]]>1,Print["User must specify a single gauge group."],True,(alg=DeleteDuplicates[alg][[1]];parsed=DeleteCases[SortBy[({states}/.{ad[alg]->adjointDynkinLabel[alg],ad->adjointDynkinLabel[alg],F[alg]->w[Head[alg]]@@PadRight[{1},First[alg]],F->w[Head[alg]]@@PadRight[{1},First[alg]]}),representationDimension[#]&],0];If[Not[parsed==={states}],numberOfIndependentColourTensors@@parsed,Set[numberOfIndependentColourTensors[states],(adj=adjointDynkinLabel[alg];nAdj=Total[parsed/.{Times[q_,adj]:>q,adj->1,times[q_,adj]:>q,w[a_][wt__]:>0}];fList=DeleteCases[(parsed/.{Times[q_Integer,w[r_][wt__]]:>Sequence@@(w[r][wt]&/@Range[q])}),adj];decomp=tensorProductDecomposition@@SortBy[Join[fList,adj&/@Range[Floor[nAdj/2]]],representationDimension[#]&];If[EvenQ[nAdj],Total[(List@@decomp)/.times[q_,r_]:>q^2],right=tensorProductDecomposition[decomp,adj];rules=Association[List@@decomp/.{times[no_,w[a_][wt__]]:>Rule[w[a][wt],no]}];Total[DeleteCases[((List@@right)/.rules),times[q_,w[a_][wt__]]]/.times->Times]])]])]];


(* ::Subsubsection::Closed:: *)
(*Backend:*)


tools`highestWeightSpindle[w[alg_Symbol][highestWeight__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{highestWeight}]]]:=tools`highestWeightSpindle[w[alg][highestWeight]]=Module[{t00=AbsoluteTime[],algebra=tools`parseAlgebra[alg[Length[{highestWeight}]]],weylOrbits,nextSeed,eqns,rule,m,met,cart,k=Length[{highestWeight}],\[Lambda]={highestWeight},weights,cartI},cart=cartan[algebra];cartI=inverse[cartan[algebra]];met=weightMetric[algebra];weights=DeleteDuplicates@(Join@@(NestWhile[Function[{wts},Append[wts,DeleteDuplicates[Join@@(Function[{wt},Module[{subt=Join@@(Function[{cart,int},cart*#&/@Range[int]]@@@Select[Transpose[{cart,wt}],Positive[Last[#]]&])},(wt-#)&/@subt]]/@wts[[-1]])]]],{{{highestWeight}}},Length[Last[#]]>0&][[1;;-2]]));weylOrbits={(Join@@FixedPoint[Function[{list},Module[{new=DeleteDuplicates[Join@@(Function[{wt},DeleteDuplicates[wt-2#*(# . met . wt)/(# . met . #)&/@cart]]/@list[[-1]])]},new=Select[new,Not[MemberQ[Join@@list,#]]&];If[Length[new]==0,list,Append[list,new]]]],{{First[weights]}}])};nextSeed=Select[weights,Not[MemberQ[Join@@weylOrbits,#]]&,1];While[Length[nextSeed]>0,weylOrbits=Append[weylOrbits,(Join@@FixedPoint[Function[{list},Module[{new=DeleteDuplicates[Join@@(Function[{wt},DeleteDuplicates[wt-2#*(# . met . wt)/(# . met . #)&/@cart]]/@list[[-1]])]},new=Select[new,Not[MemberQ[Join@@list,#]]&];If[Length[new]==0,list,Append[list,new]]]],{nextSeed}])];nextSeed=If[Length[Join@@weylOrbits]==Length[weights],{},Select[weights,Not[MemberQ[Join@@weylOrbits,#]]&,1]];];rule=Association@(Join@@Function[{list},m@#->m@First[list]&/@list]/@weylOrbits[[2;;-1]]);eqns=((Function[{wt},Module[{d=(\[Lambda]+1) . met . (\[Lambda]+1)-(wt+1) . met . (wt+1),\[Alpha]s=Select[Normal@positiveWeights[algebra],MemberQ[weights,wt+#]&]},m[wt]-Total[Join@@(Function[{\[Alpha]},2m[wt+\[Alpha] #](wt+\[Alpha]*#) . met . \[Alpha]/d&/@Range[Select[Range[100],Not[MemberQ[weights,wt+# \[Alpha]]]&,1][[1]]-1]]/@\[Alpha]s)]]]/@weylOrbits[[2;;-1,1]]));weights=Transpose[{Join@@(Function[{a,b},a&/@Range[b]]@@@Transpose[{Prepend[m/@weylOrbits[[2;;-1,1]]/.First[Solve[(eqns/.Association[m@#->1&/@First[weylOrbits]]/.rule)==0]],1],Length/@weylOrbits}]),Join@@weylOrbits}];weights=SortBy[#,-Reverse[Last[#] . cartI]&]&/@SortBy[GatherBy[weights,Total[Last[#] . cartI]&],-Total[Last[First@#] . cartI]&];If[AbsoluteTime[]-t00>1,Print["determination of the spindle for representation ",w[alg]@@{highestWeight}," (",representationDimension[w[alg][highestWeight]],") of ",algebra," required ",niceTime[AbsoluteTime[]-t00]]];weights];
tools`highestWeightLattice[w[alg_Symbol][highestWeight__Integer]]/;tools`legalAlgebraTrueQ[alg[Length[{highestWeight}]]]:=Join@@tools`highestWeightSpindle[w[alg][highestWeight]];

tools`weylReflect[{mult_Integer,head_[weight___Integer]},cart_List]:=Set[tools`weylReflect[{mult,{weight}},cart],Which[Count[{weight},-1]>0,Nothing,Min[{weight}+1]>0,{mult,{weight}},True,Module[{pos={First@Flatten[Position[Negative[{weight}+1],True]]}},tools`weylReflect[{mult Power[-1,Length[pos]],{weight}-Total[({weight}[[pos]]+1)*cart[[pos]]]},cart]]]];

tools`completeSymmetricPolynomial[n_Integer?NonNegative]:=Module[{h},h[0]=1;Do[h[k]=Expand[1/k Sum[\[Chi][j] h[k-j],{j,1,k}]],{k,1,n}];h[n]];
tools`elementarySymmetricPolynomial[n_Integer?NonNegative]:=Module[{e},e[0]=1;Do[e[k]=Expand[1/k Sum[(-1)^(j-1) \[Chi][j] e[k-j],{j,1,k}]],{k,1,n}];e[n]];

tools`symPowerWeightLattice[w[alg_][dynkinLabels__], n_Integer]:=tools`symPowerWeightLattice[w[alg][dynkinLabels],n]=tools`symPowerWeightLattice[alg[Length[{dynkinLabels}]],Normal@representationWeights[w[alg][dynkinLabels]], n];
tools`symPowerWeightLattice[alg_,weights_List,n_Integer]:=Module[{exp, symChar,symLattice,cartI=inverse[cartan[alg]]},SortBy[((If[Head[#]===Plus,List@@#,{#}]&@(Expand[(tools`completeSymmetricPolynomial[n]/.\[Chi][q_Integer]:>Total[exp/@(q weights)])]//.{Power[exp[q_],r_]:>exp[r q],exp[q_]exp[r_]:>exp[q+r]}))/.{q_Integer exp[y_]:>{q,y},exp[y_]:>{1,y}}),-Total[Last[#] . cartI]&]];
tools`symPowerWeightLattice[args_, n_Integer]:=tools`symPowerWeightLattice[args, n]=tools`symPowerWeightLattice[Cases[args,w[alg_][dynkinLabels__Integer]:>alg[Length[{dynkinLabels}]],{0,\[Infinity]}][[1]],Normal@representationWeights[args], n];

tools`antiSymPowerWeightLattice[w[alg_][dynkinLabels__], n_Integer]:=tools`antiSymPowerWeightLattice[w[alg][dynkinLabels], n]=tools`antiSymPowerWeightLattice[alg[Length[{dynkinLabels}]],Normal@representationWeights[w[alg][dynkinLabels]], n];
tools`antiSymPowerWeightLattice[alg_,weights_List,n_Integer]:=Module[{exp, symChar,symLattice,cartI=inverse[cartan[alg]]},SortBy[((If[Head[#]===Plus,List@@#,{#}]&@(Expand[(tools`elementarySymmetricPolynomial[n]/.\[Chi][q_Integer]:>Total[exp/@(q weights)])]//.{Power[exp[q_],r_]:>exp[r q],exp[q_]exp[r_]:>exp[q+r]}))/.{q_Integer exp[y_]:>{q,y},exp[y_]:>{1,y}}),-Total[Last[#] . cartI]&]];
tools`antiSymPowerWeightLattice[args_, n_Integer]:=tools`antiSymPowerWeightLattice[args, n]=tools`antiSymPowerWeightLattice[Cases[args,w[alg_][dynkinLabels__Integer]:>alg[Length[{dynkinLabels}]],{0,\[Infinity]}][[1]],Normal@representationWeights[args], n];

tools`highestWeightLabels[type_][latticeData_List]:=plus@@SortBy[NestWhile[Function[{dat},Module[{rest=dat[[2]],removal,top,mult},{mult,top}=First[rest];removal=Join[Rule[#2,-mult #1]&@@@tools`highestWeightLattice[w[type]@@top],#->0&/@rest[[All,2]]];{Prepend[dat[[1]],times[mult,w[type]@@top]],DeleteCases[Transpose[{Total/@(rest/.removal),rest[[All,2]]}],{0,x_}]}]],{{},latticeData},Length[#[[2]]]>0&][[1]],representationDimension[#[[2]]]&];


