fundamentalRep[algin_Symbol[kin_Integer],no_Integer]/;tools`legalAlgebraTrueQ[algin[kin]]&&no<=First[tools`parseAlgebra[algin[kin]]]:=Module[{out,algebra=tools`parseAlgebra[algin[kin]],alg,k},alg=Head[algebra];k=First[algebra];out=Module[{t0=AbsoluteTime[],target=IdentityMatrix[k][[no]]},If[Not[algebra===algin[kin]],fundamentalRep[algebra,no],If[MemberQ[{b,d},Head[algebra]]&&(algebra[[1]]>8),"?",(Catch[(If[AbsoluteTime[]-t0>1,Print[niceTime[AbsoluteTime[]-t0]," required to generate concrete generators for ",w[alg]@@(IdentityMatrix[k][[no]])," of ",algebra]];If[True,Set[fundamentalRep[alg[k],no],#],#])&@tools`standardizeRep[Which[no==1,Throw@fundamentalRep[algebra],target===List@@adjointDynkinLabel[algebra],Throw@adjointRep[algebra],((Head[algebra]===d)||(Head[algebra]===b))&&no==k,Throw@spinorRep[algebra],Head[algebra]===d&&no==k-1,Throw@spinor2Rep[algebra],Head[algebra]===a,If[no<=k/2,antiSymPower[fundamentalRep[algebra],no],antiSymPower[conjugateRep@fundamentalRep[algebra],k+1-no]],Head[algebra]===b,antiSymPower[fundamentalRep[algebra],no],Head[algebra]===c,productRepProjectors[target,fundamentalRep[algebra,no-1],fundamentalRep[algebra]][[1,2]],Head[algebra]===d,antiSymPower[fundamentalRep[algebra],no],algebra===f[4],Which[no==2,productRepProjectors[{0,1,0,0},fundamentalRep[algebra],fundamentalRep[algebra]][[1,2]],True,productRepProjectors[{0,0,1,0},adjointRep[algebra],adjointRep[algebra]][[1,2]]],algebra===e[6],Which[no==5,conjugateRep[fundamentalRep[e[6]]],no==2,antiSymPower[fundamentalRep[e[6]],2],no==3,antiSymPower[fundamentalRep[e[6]],3],no==4,antiSymPower[conjugateRep@fundamentalRep[e[6]],2]],algebra===e[7],Which[no==7,productRepProjectors[{0,0,0,0,0,0,1},fundamentalRep[e[7]],adjointRep[e[7]]][[1,2]],no==2,productRepProjectors[{0,1,0,0,0,0,0},fundamentalRep[e[7]],fundamentalRep[e[7]]][[1,2]],no==5,productRepProjectors[{0,0,0,0,1,0,0},adjointRep[e[7]],adjointRep[e[7]]][[1,2]],no==3,productRepProjectors[{0,0,1,0,0,0,0},fundamentalRep[e[7],6],fundamentalRep[e[7],7]][[1,2]],no==4,productRepProjectors[{0,0,0,1,0,0,0},fundamentalRep[e[7],7],fundamentalRep[e[7],7]][[1,2]]],algebra===e[8],Which[no==7,productRepProjectors[{0,0,0,0,0,0,1,0},fundamentalRep[e[8]],fundamentalRep[e[8]]][[1,2]],no==2,productRepProjectors[{0,1,0,0,0,0,0,0},fundamentalRep[e[8]],fundamentalRep[e[8]]][[1,2]],no==8,productRepProjectors[{0,0,0,0,0,0,0,1},fundamentalRep[e[8],7],fundamentalRep[e[8],7]][[1,2]],no==3,productRepProjectors[{0,0,1,0,0,0,0,0},fundamentalRep[e[8],7],fundamentalRep[e[8],7]][[1,2]],no==6,productRepProjectors[{0,0,0,0,0,1,0,0},fundamentalRep[e[8],7],fundamentalRep[e[8],7]][[1,2]],no==4,productRepProjectors[{0,0,0,1,0,0,0,0},fundamentalRep[e[8],2],fundamentalRep[e[8],2]][[1,2]],no==5,productRepProjectors[{0,0,0,0,1,0,0,0},fundamentalRep[e[8],8],fundamentalRep[e[8],8]][[1,2]]]]]])]]];Set[tools`normalRepresentationQ[out],True];Set[dynkinLabel[out],w[Head[algebra]]@@IdentityMatrix[k][[no]]];Set[representationAlgebra[out],algebra];If[Head[tools`drawTensor[out]]===tools`drawTensor,(Set[tools`stylizedRepData[out],{"\!\(\*SubscriptBox[\(F\),\("<>ToString[no]<>"\)]\)","f",algebra,w[Head[algebra]]@@IdentityMatrix[k][[no]],RGBColor[0.2,0.2,0.6]}];Set[tools`drawTensor[out],tools`graphicalDotPower[w[Head[algebra]]@@IdentityMatrix[k][[no]],3]];)];out];


(* ::Subsection:: *)
(*Spinor Representations of SO(n)*)


spinorRep[b[k_Integer]]/;MemberQ[tools`bSeriesSpinorRepData[[All,1]],b[k]]:=spinorRep[b[k]]=Module[{out=tools`parseRepresentationData[tools`bSeriesSpinorRepData[[k-1]]]},Set[tools`normalRepresentationQ[out],True];Set[tools`normalRepresentationQ[out],True];Set[representationAlgebra[out],b[k]];Set[tools`stylizedRepData[out],{"S","s",b[k],w[b]@@PadLeft[{1},k],RGBColor[0.2,0.5,0.2]}];Set[tools`drawTensor[out],tools`graphicalDotPower[w[b]@@PadLeft[{1},k],3]];out];
spinorRep[d[k_Integer]]/;MemberQ[tools`dSeriesSpinorRepData[[All,1]],d[k]]:=spinorRep[d[k]]=Module[{out=tools`parseRepresentationData[tools`dSeriesSpinorRepData[[k-3]]]},Set[tools`normalRepresentationQ[out],True];Set[tools`normalRepresentationQ[out],True];Set[representationAlgebra[out],d[k]];Set[tools`stylizedRepData[out],{"\!\(\*SubscriptBox[\(S\), \(1\)]\)","s",d[k],w[d]@@PadLeft[{1},k],RGBColor[0.2,0.5,0.2]}];Set[tools`drawTensor[out],tools`graphicalDotPower[w[d]@@PadLeft[{1},k],3]];out];
spinorRep[alg_]/;Not[tools`parseAlgebra[alg]===alg]:=spinorRep[tools`parseAlgebra[alg]];

spinor2Rep[d[k_Integer]]/;OddQ[k]&&5<=k<=7:=spinor2Rep[d[k]]=Module[{out=tools`standardizeRep[conjugateRep[spinorRep[d[k]]]]},Set[tools`normalRepresentationQ[out],True];Set[tools`normalRepresentationQ[out],True];Set[representationAlgebra[out],d[k]];Set[tools`stylizedRepData[out],{"\!\(\*SubscriptBox[\(S\), \(2\)]\)","s",d[k],w[d]@@PadLeft[{1,0},k],RGBColor[0.2,0.5,0.2]}];Set[tools`drawTensor[out],tools`graphicalDotPower[w[d]@@PadLeft[{1,0},k],3]];out];
spinor2Rep[d[k_Integer]]/;EvenQ[k]&&4<=k<=8:=spinor2Rep[d[k]]=Module[{out=tools`parseRepresentationData[tools`dSeriesSpinor2RepData[[k/2-1]]]},Set[tools`normalRepresentationQ[out],True];Set[representationAlgebra[out],d[k]];Set[tools`stylizedRepData[out],{"\!\(\*SubscriptBox[\(S\), \(2\)]\)","s",d[k],w[d]@@PadLeft[{1,0},k],RGBColor[0.2,0.5,0.2]}];Set[tools`drawTensor[out],tools`graphicalDotPower[w[d]@@PadLeft[{1,0},k],3]];out];
