(* ::Subsection:: *)
(*Trivial Representations*)


trivialRep[alg_]/;tools`legalAlgebraTrueQ[alg]:=SparseArray[{},{1,Dimensions[fundamentalRep[tools`parseAlgebra[alg]]][[2]],1}];


(* ::Subsection:: *)
(*Adjoint Representations and Structure Constants*)


adjointRep[alg_]/;tools`legalAlgebraTrueQ[alg]:=Module[{fund=fundamentalRep[tools`parseAlgebra[alg]]},If[Head[fund]===SparseArray,Module[{ad=inducedAdjoint[fund]},Set[tools`normalRepresentationQ[ad],True];Set[adjointRep[alg],ad]]]];
adjointRep[rep_SparseArray]:=inducedAdjoint[rep];


