killingMetric[rep_SparseArray]/;Length[rep["NonzeroValues"]]>0&&(SameQ@@Dimensions[rep][[{1,-1}]]):=killingMetric[representationAlgebra[rep]];
killingMetricInverse[rep_SparseArray]/;Length[rep["NonzeroValues"]]>0&&(SameQ@@Dimensions[rep][[{1,-1}]]):=killingMetricInverse[representationAlgebra[rep]];


(* ::Subsubsection:: *)
(*Backend:*)


tools`eSeriesFundamentalRepData:=tools`eSeriesFundamentalRepData=Uncompress["1:"];
tools`bSeriesSpinorRepData:=tools`bSeriesSpinorRepData=Uncompress["1:"];
tools`dSeriesSpinorRepData:=tools`dSeriesSpinorRepData=Uncompress["1:"];
tools`dSeriesSpinor2RepData:=tools`dSeriesSpinor2RepData=Uncompress["1:"];


tools`standardizeRep[rep_]:=Module[{marks=Normal@representationRoots[rep],order},order=OrderingBy[marks,{-Total[#],-#}&];rep[[order,All,order]]];
