(* ::Subsection:: *)
(*Irreducible Representations of a[1] in Chevalley Basis*)


a1Rep[weight_Integer]/;weight>=0:=a1Rep[weight]=Module[{out=If[weight===0,SparseArray[{},{1,3,1}],Transpose[SparseArray@List[SparseArray[Band[{2,1}]->If[EvenQ[weight],Power[-1,Range[weight]],1]*Range[weight],{weight+1,weight+1}],SparseArray[Band[{1,1}]->Reverse[Range[-weight/2,weight/2]],{weight+1,weight+1}],SparseArray[Band[{1,2}]->Reverse@(If[EvenQ[weight],Power[-1,Range[weight]+1],1]*Range[weight]),{weight+1,weight+1}]],{2,1,3}]]},Set[representationAlgebra[out],a[1]];Set[tools`normalRepresentationQ[out],True];Set[tools`stylizedRepData[out],{ToString[weight+1],"r",a[1],w[a][weight],tools`repColour[w[a][weight]]}];Set[tools`drawTensor[out],tools`graphicalDotPower[w[a][weight],3]];out];
