(* ::Section:: *)
(*Building Other Representations from Representations*)


(* ::Subsection:: *)
(*Conjugation of Representations*)


conjugateRep[rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]:=Module[{out=(-Transpose[rep,{3,2,1}]),label0=tools`stylizedRepData[rep]},If[tools`normalRepresentationQ[rep],Set[tools`normalRepresentationQ[out],True]];Set[representationAlgebra[out],label0[[3]]];Set[dynkinLabel[out],conjugateRep[dynkinLabel[rep]]];Set[tools`stylizedRepData[out],{If[Head[First[label0]]===String,OverBar[First[label0]],First[First[label0]]],If[Head[label0[[2]]]===String,OverBar[label0[[2]]],First[label0[[2]]]],label0[[3]],(label0[[4]]/.{w[alg_Symbol][weights__Integer]:>wc[alg][weights],wc[alg_Symbol][weights__Integer]:>w[alg][weights]}),Last[label0]}];Set[tools`drawTensor[out],tools`graphicalDotPower[(label0[[4]]/.{w[alg_Symbol][weights__Integer]:>wc[alg][weights],wc[alg_Symbol][weights__Integer]:>w[alg][weights]}),3]];out];


(* ::Subsection:: *)
(*Adjoint Representations*)


inducedAdjoint[rep_SparseArray]/;(SameQ@@Dimensions[rep][[{1,-1}]]):=If[Length[rep["NonzeroValues"]]==0,SparseArray[{},{1,1,1}*Dimensions[rep][[2]]],inducedAdjoint[rep]=SparseArray[#-Transpose[#,{2,1,3}]]&@dot[repTrace[rep,3,False],inverse[repTrace[rep,2,False]]]];


(* ::Subsection:: *)
(*Tensor-Products and Powers*)


(*tensor-product-representations of concrete representations*)
productRep[repA_SparseArray]:=repA;
productRep[repA_SparseArray,repB_SparseArray]/;Dimensions[repA][[2]]===Dimensions[repB][[2]]:=Module[{algList=representationAlgebra/@{repA,repB}},If[Not[SameQ@@algList],Print["Representations must both be of the same algebra."],Module[{out=Transpose[Join@@Transpose[Join@@Transpose[SparseArray[SparseArray[TensorProduct[#,SparseArray[{x_,x_}:>1,Dimensions[repB][[{1,-1}]]]]&/@Transpose[repA,{2,1,3}]]+SparseArray[TensorProduct[SparseArray[{x_,x_}:>1,Dimensions[repA][[{1,-1}]]],#]&/@Transpose[repB,{2,1,3}]]],{3,1,4,2,5}],{4,3,1,2}],{3,2,1}],labelDat=tools`stylizedRepData/@{repA,repB}},Set[tools`normalRepresentationQ[out],True];Set[representationAlgebra[out],First[algList]];Set[tools`stylizedRepData[out],{ToString[First[Dimensions[out]]],"r",labelDat[[1,3]],times[labelDat[[1,4]],labelDat[[2,4]]],RGBColor[0.2,0.2,0.6]}];Set[representationAlgebra[out],labelDat[[1,3]]];Set[tools`drawTensor[out],tools`graphicalDotPower[times[labelDat[[1,4]],labelDat[[2,4]]],3]];Set[dynkinLabel[out],tensorProductDecomposition[dynkinLabel[repA],dynkinLabel[repB]]];out]]];
