(*tensor-power of concrete representations*)
repPower[repA_SparseArray,0]:=SparseArray[{},{1,Dimensions[repA][[2]],1}];repPower[repA_SparseArray,1]:=repA;repPower[repA_SparseArray,2]:=repPower[repA,2]=productRep[repA,repA];
repPower[repA_SparseArray,q_Integer]/;q>2:=repPower[repA,q]=Module[{out=productRep[repPower[repA,Floor[q/2]],repPower[repA,Ceiling[q/2]]],labelDat=tools`stylizedRepData[repA]},Set[representationAlgebra[out],labelDat[[3]]];Set[tools`stylizedRepData[out],{ToString[First[Dimensions[out]]],"r",labelDat[[3]],power[labelDat[[4]],q],labelDat[[-1]]}];Set[tools`drawTensor[out],tools`graphicalDotPower[power[labelDat[[4]],q],3]];out];

(*symmetric tensor-powers of concrete representations*)
symPower[repA_SparseArray,q_Integer]/;q>=1:=If[q==1,repA,Module[{scale,aq=repPower[repA,q],out,alg=representationAlgebra[repA],label=tools`stylizedRepData[repA],pwrs,project,leftP,rightP,d=Dimensions[repA][[-1]],tuples,imageRule,scale2},tuples=Tuples[Range[d],{q}];imageRule=Association[Thread[DeleteDuplicates[Sort/@tuples]->Range[Length[DeleteDuplicates[Sort/@tuples]]]]];pwrs=(d^(q-#1)&)/@Range[q];leftP=Transpose[SparseArray[({pwrs . (#1-1)+1,Sort[#1]/. imageRule}->1&)/@tuples,{d^q,Length[imageRule]}]];rightP=SparseArray[({pwrs . (#1-1)+1,Sort[#1]/. imageRule}->Function[{tuple},Module[{grps=Count[tuple,#]&/@DeleteDuplicates[tuple]},Times@@(grps!)]][#]&)/@tuples,{d^q,Length[imageRule]}];out=SparseArray[1/q! (dot[leftP,aq,rightP])];Set[tools`normalRepresentationQ[out],True];Set[representationAlgebra[out],alg];Set[tools`stylizedRepData[out],{ToString[First[Dimensions[out]]],"r",alg,powers[label[[4]],q],label[[-1]]}];Set[tools`drawTensor[out],tools`graphicalDotPower[powers[label[[4]],q],3]];If[Head[Head[dynkinLabel[repA]]]===w,Set[dynkinLabel[out],symPowerDecomposition[dynkinLabel[repA],q]](*,Set[dynkinLabel[out],tools`highestWeightLabels[Head[representationAlgebra[repA]]][tools`symPowerWeightLattice[representationAlgebra[repA],Normal[representationWeights[repA,True]],q]]]*)];out]];

(*antisymmetric tensor-powers of concrete representations*)
antiSymPower[repA_SparseArray,q_Integer]/;q>=1&&q<=First[Dimensions[repA]]:=If[q==1,repA,Module[{alg=representationAlgebra[repA],out,aq=repPower[repA,q],label=tools`stylizedRepData[repA],pwrs,project,d=Dimensions[repA][[-1]],tuples,imageRule},tuples=Subsets[Range[d],{q}];imageRule=Association[Thread[tuples->Range[Binomial[d,q]]]];pwrs=(d^(q-#1)&)/@Range[q];project=SparseArray[({pwrs . (#1-1)+1,Sort[#1]/. imageRule}->Signature[#1]&)/@Join@@Permutations/@tuples,{d^q,Binomial[d,q]}]; out=SparseArray[1/q!dot[Transpose[project] , aq , project]];Set[tools`normalRepresentationQ[out],True];Set[representationAlgebra[out],alg];Set[tools`stylizedRepData[out],{ToString[First[Dimensions[out]]],"r",alg,powera[label[[4]],q],label[[-1]]}];Set[tools`drawTensor[out],tools`graphicalDotPower[powera[label[[4]],q],3]];If[Head[Head[dynkinLabel[repA]]]===w,Set[dynkinLabel[out],antiSymPowerDecomposition[dynkinLabel[repA],q]]];out]];


(* ::Subsection:: *)
(*Projections of Tensor Product Reps into Casimir Eigen-Subspaces*)


(*projectors of product representations into quadratic-casimir eigenspaces*)
productRepProjectors[repA_SparseArray,repB_SparseArray]/;SameQ@@(representationAlgebra/@{repA,repB}):=productRepProjectors[{},repA,repB];productRepProjectors[target_List,repA_SparseArray,repB_SparseArray]/;SameQ@@(representationAlgebra/@{repA,repB}):=Module[{c2List,prod,algebra=representationAlgebra[repA],preimageWeights,imageDecomp,imageWeights,imageEigenvalues,range,pos,projDat,out},prod=If[SameQ@@{repA,repB},{productRep[symPower[repA,2]],productRep[antiSymPower[repA,2]]},{productRep[repA,repB]}];c2List=casimirC2/@prod;preimageWeights=Cases[dynkinLabel[#],w[q_][x__Integer],{0,\[Infinity]}]&/@{repA,repB};imageDecomp=tensorProductDecomposition@@@Tuples[preimageWeights];imageWeights=DeleteDuplicates[Join[Cases[imageDecomp,w[q_][x__Integer],{0,\[Infinity]}]]];imageEigenvalues=casimirEigenvalue/@imageWeights;range=If[target==={},Range[Length[DeleteDuplicates@imageEigenvalues]],pos=Flatten[Position[List@@@imageWeights,List@@target]];If[Length[pos]==0,{},Flatten[Position[DeleteDuplicates[imageEigenvalues],imageEigenvalues[[pos[[1]]]]]]]];projDat=If[Length[DeleteDuplicates[imageEigenvalues]]==1,{{imageWeights,SparseArray[{x_,x_}:>1,Dimensions[#]]}}&/@c2List,Select[#,Tr[#[[-1]]]>0&]&/@(Function[{ls,mats},{imageWeights[[Flatten[Position[imageEigenvalues,ls[[1]]]]]],SparseArray[1/Times@@((ls[[1]]-#)&/@ls[[2;;-1]]) (dot@@mats[[2;;-1]])]}]@@@#&/@(Transpose/@Partition[#,Length[#],1,1][[range]]&/@(Table[{\[Lambda],((SparseArray[(c2-SparseArray[{x_,x_}:>\[Lambda],Dimensions[c2]])]))},{c2,c2List},{\[Lambda],DeleteDuplicates[imageEigenvalues]}])))];out=Join@@(Function[{pList,seed},Function[{labels,projector},Module[{indepR=tools`independentRows[projector],r,firstDat,induced,ord,sym},r=projector[[indepR]];firstDat={r,seed,dot[projector,Transpose[r],SparseArray[inverse[dot[r,Transpose[r]]]]]};ord=If[Tr[projector]==1,{1},Ordering[{-Total[#],Reverse[#]}&/@Normal[representationRoots[dot@@firstDat]]]];induced=dot@@{firstDat[[1,ord]],firstDat[[2]],firstDat[[3,All,ord]]};sym=Which[Length[labels]>1,SparseArray[{x_,x_}:>1,{Length[First[firstDat]],Length[First[firstDat]]}],List@@labels[[1]]===Normal[dynkinLabel[algebra]]&&Length[DeleteDuplicates[Dimensions[induced]]]==1,findSimilarity[induced,adjointRep[algebra]],List@@labels[[1]]===preimageWeights[[1]]&&Dimensions[induced]===Dimensions[repA],findSimilarity[induced,repA],List@@labels[[1]]===preimageWeights[[2]]&&Dimensions[induced]===Dimensions[repB],findSimilarity[induced,repB],List@@labels[[1]]===PadRight[{1},algebra[[1]]]&&First[Dimensions[induced]]===Length[fundamentalRep[algebra]],findSimilarity[induced,fundamentalRep[algebra]],True,SparseArray[{x_,x_}:>1,{Length[First[firstDat]],Length[First[firstDat]]}]];{labels,dot@@{inverse[sym],firstDat[[1,ord]],firstDat[[2]],firstDat[[3,All,ord]],sym},dot[If[repA===repB,If[Dimensions[seed][[1]]==(Binomial[Dimensions[repA][[1]],2]),tools`antiSymPartition[firstDat[[3,All,ord]],Dimensions[repA][[1]]],tools`symPartition[firstDat[[3,All,ord]],Dimensions[repA][[1]]]],Partition[firstDat[[3,All,ord]],Dimensions[repB][[1]]]],sym]}]]@@@pList]@@@Transpose[{projDat,prod}]);Function[{dat},Module[{l=If[Length[dat[[1]]]>1,plus@@(times[1,#]&/@(dat[[1]])),dat[[1,1]]]},Set[representationAlgebra[dat[[2]]],algebra];Set[tools`normalRepresentationQ[dat[[2]]],True];If[Head[tools`drawTensor[dat[[2]]]]===tools`drawTensor,Set[tools`stylizedRepData[dat[[2]]],{ToString[First@Dimensions[dat[[2]]]],"r",algebra,l,tools`repColour[w[a][1,0,0,0]]}];];]]/@out;out];

(*constructing an explicit (largexlarge) projector from clebsch-data*)
fromClebschToProjector[clebsch_SparseArray]:=dot[(Join@@clebsch),inverse[Transpose[Join@@clebsch] . (Join@@clebsch)],Transpose[Join@@clebsch]];

