fromClebschToLRprojectors[clebsch_SparseArray]:={dot[inverse[dot[Transpose[Join@@clebsch],(Join@@clebsch)]],Transpose[Join@@clebsch]],(Join@@clebsch)};


(* ::Subsection:: *)
(*Summing of Representations*)


repSum[repA_SparseArray,repB_SparseArray]:=Module[{rulesA=ArrayRules[repA][[1;;-2]],rulesB=List@@@ArrayRules[repB][[1;;-2]],dimA=Dimensions[repA][[1]],out,labelDat=tools`stylizedRepData/@{repA,repB}},out=SparseArray[Join[rulesA,Rule[(#1+{dimA,0,dimA}),#2]&@@@rulesB],ReplacePart[Dimensions[repA]+Dimensions[repB],2->Dimensions[repA][[2]]]];tools`stylizedRepData[out]={ToString[First[Dimensions[out]]],"r",labelDat[[1,3]],tools`addDynkinLabels[labelDat[[1,4]],labelDat[[2,4]]],RGBColor[0.2,0.2,0.6]};Set[dynkinLabel[out],tools`addDynkinLabels[labelDat[[1,4]],labelDat[[2,4]]]];Set[tools`normalRepresentationQ[out],True];Set[representationAlgebra[out],labelDat[[1,3]]];Set[tools`drawTensor[out],tools`graphicalDotPower[tools`addDynkinLabels[labelDat[[1,4]],labelDat[[2,4]]],3]];out];
repSum[repA_SparseArray,repC__SparseArray]:=repSum[repSum[repA,First[{repC}]],Sequence@@{repC}[[2;;-1]]];
repSum[n_Integer,repA_SparseArray]:=repSum@@(repA&/@Range[n]);repSum[repA_SparseArray,n_Integer]:=repSum@@(repA&/@Range[n]);


(* ::Subsubsection::Closed:: *)
(*Backend:*)


tools`addDynkinLabels[label1_,label2_]/;(Count[label1,w[alg_Symbol][weights__Integer],{0,\[Infinity]}]>0)&&(Count[label2,w[alg_Symbol][weights__Integer],{0,\[Infinity]}]>0):=Module[{left,right},plus@@(times[Total[#[[All,1]]],#[[1,2]]]&/@GatherBy[SortBy[Join@@(Which[Head[#]===plus,((List@@#)/.times[x_Integer,y_]:>{x,y}),Head[#]===times,(({#})/.times[x_Integer,y_]:>{x,y}),True,{{1,#}}]&/@{label1,label2}),representationDimension[Last[#]]&],Last])];

tools`antiSymPartition[array_,dim_]:=Module[{rules=Association[Thread[Rule[Range[Binomial[dim,2]],Subsets[Range[dim],{2}]]]],rules0=List@@@ArrayRules[array][[1;;-2]]},tools`cleanArray[SparseArray[(#-Transpose[#,Join[{2,1},Range[Length[Dimensions[array]]-1]+2]])]]&@SparseArray[Function[{slots,val},Join[(slots[[1]]/.rules),slots[[2;;-1]]]->val]@@@rules0,Join[{dim,dim},Dimensions[array][[2;;-1]]]]];
