(* ::Section:: *)
(*Analysis and Characteristics of Concrete Representations*)


(* ::Subsection:: *)
(*Characteristics of Concrete Representations*)


representationAlgebra[rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]](*&&tools`normalRepresentationQ[rep]*):=If[Length[rep["NonzeroValues"]]==0,tools`guessAlgebra[Dimensions[rep][[2]]],representationAlgebra[rep]=If[Length[DeleteDuplicates[Dimensions[rep]]]>1,representationAlgebra[inducedAdjoint[rep]],Module[{adj=inducedAdjoint[rep]},If[Not[Equal[adj,rep]],representationAlgebra[adj],Module[{highestMark=Normal@First[representationRoots[rep,True]]},Which[MemberQ[{{1,2,3,2,1,2},{1,2,3,4,3,2,2},{2,3,4,5,6,4,2,3},{2,4,3,2},{3,2}},highestMark],(highestMark/.Thread[Rule[{{1,2,3,2,1,2},{1,2,3,4,3,2,2},{2,3,4,5,6,4,2,3},{2,4,3,2},{3,2}},{e[6],e[7],e[8],f[4],g[2]}]]),DeleteDuplicates[highestMark]=={1},a[Length[highestMark]],DeleteDuplicates[highestMark[[2;;-1]]]=={2},b[Length[highestMark]],DeleteDuplicates[highestMark[[1;;-2]]]=={2},c[Length[highestMark]],DeleteDuplicates[highestMark[[2;;-3]]]==={2}&&DeleteDuplicates[highestMark[[{1,-2,-1}]]]==={1},d[Length[highestMark]],True,"?"]]]]]];

representationDimension[rep_SparseArray]:=First[Dimensions[rep]];


irreducibleRepresentationQ[rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]:=If[True(*tools`normalRepresentationQ[rep]*),Module[{marks=Normal[representationRoots[rep,True]],algebra=representationAlgebra[rep]},If[Count[marks,First[marks]]>1,False,Last[Dimensions[rep]]==representationDimension[w[Head[algebra]]@@(First[marks] . cartan[algebra])]]],"?"];

(*checking a representation's reality from its weights in the Chevalley basis*)
realRepresentationQ[rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]/;tools`normalRepresentationQ[rep]:=Length[SparseArray[#+Reverse[#]]["NonzeroValues"]]==0&@representationRoots[rep,True];

(*checking a representation's pseudo-reality from its weights in the Chevalley basis*)
pseudoRealRepresentationQ[rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]/;tools`normalRepresentationQ[rep]:=If[Not[irreducibleRepresentationQ[rep]],Print["Pseudo-reality only makes sense for irreducible representations."];False,Module[{marks=Normal[representationRoots[rep,True]],algebra=representationAlgebra[rep]},pseudoRealRepresentationQ[w[Head[algebra]]@@(First[marks] . cartan[algebra])]]];


dynkinIndex[rep_SparseArray]:=repTrace[rep,2,False][[1,-1]]/repTrace[fundamentalRep[representationAlgebra[rep]],2,False][[1,-1]];


(* ::Subsection:: *)
(*Similarity Transformations*)


selfDualityMetric[rep_SparseArray]/;realRepresentationQ[rep]:=selfDualityMetric[rep]=Module[{out=If[inducedAdjoint[rep]===rep,killingMetric[representationAlgebra[rep]],findSimilarity[rep,conjugateRep[rep]]],inv},inv=inverse[out];Set[tools`stylizedTensor[out],tools`stylizedMetric[rep]];Set[tools`drawTensor[out],tools`graphicalMetric[rep]];If[Not[TrueQ[SameQ[out,inv]]],Set[tools`stylizedTensor[inv],tools`stylizedMetric[rep,True]];Set[tools`drawTensor[inv],tools`graphicalMetric[rep,True]];];out];


(* ::Subsection:: *)
(*Weight Systems of Representations (in Chevalley Basis)*)


(*extraction of cartan subalgebra*)
cartanGenerators[rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]:=Module[{adj=Transpose@inducedAdjoint[rep],slots},slots=Select[Range[Length[adj]],Length[Diagonal[adj[[#]]]["NonzeroValues"]]==Length[adj[[#]]["NonzeroValues"]]&];rep[[All,slots,All]]];

(*Weight systems for concrete (not-necessarily-irreducible) representations*)
representationRoots[rep_SparseArray,sortedQ_:False]:=Module[{direct=Transpose[Diagonal/@Transpose[cartanGenerators[rep],{2,1,3}]]},If[TrueQ[sortedQ],SparseArray[SortBy[Normal[direct],{-Total[#],-#}&]],SparseArray[direct]]];

representationWeights[rep_SparseArray,sortedQ_:False]:=Module[{direct=Transpose[Diagonal/@Transpose[cartanGenerators[rep],{2,1,3}]],cart=cartan[representationAlgebra[rep]]},If[TrueQ[sortedQ],SparseArray[SortBy[Normal[direct],{-Total[#],-#}&]] . cart,SparseArray[direct] . cart]];

(*Dynkin-labels for concrete representations in the Chevalley basis*)
dynkinLabel[rep_SparseArray]/;Length[Dimensions[rep]]==3&&SameQ@@Dimensions[rep][[{1,-1}]]&&tools`legalAlgebraTrueQ[representationAlgebra[rep]]:=If[Not[tools`normalRepresentationQ[rep]],"?",If[True,Set[dynkinLabel[rep],#],#]&@If[Length[rep["NonzeroValues"]]==0,Module[{algebra=representationAlgebra[rep]},w[Head[algebra]]@@PadRight[{0},First[algebra]]],Module[{marks=Normal[representationRoots[rep,True]],algebra=representationAlgebra[rep]},If[Last[Dimensions[rep]]===representationDimension[w[Head[algebra]]@@(First[marks] . cartan[algebra])],w[Head[algebra]]@@(marks[[1]] . cartan[algebra]),Module[{lattices,lattice,remainingLattice,removal,removalRule},remainingLattice={Count[marks,#],# . cartan[algebra]}&/@DeleteDuplicates[marks];removal={remainingLattice[[1,1]],tools`highestWeightLattice[w[Head[algebra]]@@remainingLattice[[1,2]]]};removalRule=Association[w@@#2->#1*First[removal]&@@@removal[[2]]];lattice=removal[[2]]&/@Range[removal[[1]]];remainingLattice=DeleteCases[({#1-(((w@@#2)/.removalRule)/.w[x__]:>0),#2}&@@@remainingLattice),{0,x__}];While[Length[remainingLattice]>0,(removal={remainingLattice[[1,1]],tools`highestWeightLattice[w[Head[algebra]]@@remainingLattice[[1,2]]]};removalRule=Association[w@@#2->#1*First[removal]&@@@removal[[2]]];lattice=Join[lattice,removal[[2]]&/@Range[removal[[1]]]];remainingLattice=DeleteCases[({#1-(((w@@#2)/.removalRule)/.w[x__]:>0),#2}&@@@remainingLattice),{0,x__}];)];lattices=(SortBy[#,-#[[2]]&]&/@#&/@(GatherBy[#,{-Total[#[[2]] . inverse[cartan[algebra]]]}&]&/@Reverse[lattice]));(((plus@@(times[Total[#[[All,1]]],w[Head[algebra]]@@#[[1,2]]]&/@GatherBy[lattices[[All,1,1]],Last])))/.{plus[times[1,w[a_Symbol][q__Integer]]]:>w[a][q],plus[times[mult_,w[a_Symbol][q__Integer]]]:>times[mult,w[a][q]]})]]]]];


(* ::Subsubsection::Closed:: *)
(*Backend: Tagging Representations in the Chevalley Basis*)


tools`normalRepresentationQ[rep_SparseArray]:=False;
tools`guessAlgebra[dim_Integer]:=Module[{guessList=Join[Cases[List[{e[6],78},{e[7],133},{e[8],248},{f[4],52},{g[2],14}],{x_,dim}][[All,1]],a/@Select[Range[Floor[Sqrt[dim]]],#(#+2)==dim&,1],b/@Select[Range[2,Floor[Sqrt[dim]]],#(2#+1)==dim&,1],d/@Select[Range[4,Floor[Sqrt[dim]]],#(2#-1)==dim&,1]]},If[Length[guessList]==0,"?",First[guessList]]];
tools`representationSpindles[rep_SparseArray]:=Module[{marks=Normal[representationRoots[rep,True]],algebra=representationAlgebra[rep],removalRule,remainingLattice,lattice,removal},remainingLattice={Count[marks,#],# . cartan[algebra]}&/@DeleteDuplicates[marks];removal={remainingLattice[[1,1]],tools`highestWeightLattice[w[Head[algebra]]@@remainingLattice[[1,2]]]};removalRule=Association[w@@#2->#1*First[removal]&@@@removal[[2]]];lattice=removal[[2]]&/@Range[removal[[1]]];remainingLattice=DeleteCases[({#1-(((w@@#2)/.removalRule)/.w[x__]:>0),#2}&@@@remainingLattice),{0,x__}];While[Length[remainingLattice]>0,(removal={remainingLattice[[1,1]],tools`highestWeightLattice[w[Head[algebra]]@@remainingLattice[[1,2]]]};removalRule=Association[w@@#2->#1*First[removal]&@@@removal[[2]]];lattice=Join[lattice,removal[[2]]&/@Range[removal[[1]]]];remainingLattice=DeleteCases[({#1-(((w@@#2)/.removalRule)/.w[x__]:>0),#2}&@@@remainingLattice),{0,x__}];)];SortBy[#,-#[[2]] . inverse[cartan[algebra]]&]&/@#&/@(GatherBy[#,{-Total[#[[2]] . inverse[cartan[algebra]]]}&]&/@lattice)];


(* ::Section:: *)
(*Construction of (Generally Higher-Rank) Colour Tensors from Concrete Representations*)


(* ::Subsection:: *)
(*Quadratic Casimir (as an operator)*)


casimirC2[rep_SparseArray]:=Module[{algebra=representationAlgebra[rep],out},If[tools`legalAlgebraTrueQ[algebra],out=tensorContract[{rep,rep,killingMetricInverse[algebra]},{{2,7},{3,4},{5,8}}];Set[tools`stylizedTensor[out],tools`stylizedCasimir[rep]];Set[tools`drawTensor[out],tools`graphicalCasimir[rep]];out]];


(* ::Subsection:: *)
(*Dot-Powers of Concrete Representations*)


dotPower[rep_SparseArray,1]:=rep;
dotPower[rep_SparseArray,n_Integer]:=dotPower[rep,n]=Module[{out=(tensorContract[rep&/@Range[n],Join[{Last[#1],First[#2]}&@@@Partition[Partition[Range[3(n)],3,3,1],2,1]]]),label},If[True(*TrueQ[setTrue]*),label=tools`stylizedRepData[rep];Set[tools`drawTensor[out],tools`graphicalDotPower[label[[4]],n+2]];Set[tools`stylizedTensor[out],tools`stylizedDotPower[rep,n+2]];];out];
dotPower[rep_SparseArray,{orderSequence__Integer}]:=Module[{base=dotPower[rep,Length[{orderSequence}]],label,perm,out},perm=RotateLeft[Join[{Length[{orderSequence}]+2,1},{orderSequence}+1]];out=Transpose[base,perm];If[True(*TrueQ[setTrue]*),label=tools`stylizedRepData[rep];Set[tools`drawTensor[out],tools`graphicalDotPower[label[[4]],Length[perm],perm]];Set[tools`stylizedTensor[out],tools`stylizedDotPower[rep,{orderSequence}]];If[Length[{orderSequence}]==2,Set[tools`drawTensor[out-Transpose[out,{1,3,2,4}]],Row[{tools`graphicalDotPower[label[[4]],Length[perm],perm],Style["-",FontSize->20],tools`graphicalDotPower[label[[4]],Length[perm],{1,3,2,4}]}]]];];out];


(* ::Subsection:: *)
(*(Multi-)Trace Tensors Constructed from Concrete Representations*)


repTrace[rep_SparseArray,n_Integer]:=(*repTrace[rep,n]=*)Module[{out=repTrace[rep,n,False],label=tools`stylizedRepData[rep]},If[Head[tools`drawTensor[out]]===tools`drawTensor,Set[tools`drawTensor[out],tools`graphicalTrR[label[[4]],n]];Set[tools`stylizedTensor[out],tools`stylizedTr[{label[[4]],label[[3]]},Range[n]]];];out];
repTrace[rep_SparseArray,n_Integer,False]:=repTrace[rep,n,False]=Module[{out=tensorContract[rep&/@Range[n],Join[{Last[#1],First[#2]}&@@@Partition[Partition[Range[3(n)],3,3,1],2,1,1]]]},out];
repTrace[rep_SparseArray,{q__Integer}]:=Module[{out=If[Length[{q}]==1,repTrace[rep,{q}[[1]],False],If[OrderedQ[{q}],Set[repTrace[rep,{q}],TensorProduct[repTrace[rep,{q}[[1;;-2]]],repTrace[rep,Last[{q}],False]]],Module[{lens=Range[{q}[[#]]]+Total[{q}[[1;;#-1]]]&/@Range[Length[{q}]]},lens=Join@@lens[[Ordering[Length/@lens]]];Transpose[repTrace[rep,Sort[{q}]],lens]]]]},out];
repTrace[rep_SparseArray,{{bits___Integer},y___List}]:=Module[{out=Transpose[repTrace[rep,Length/@Sort[{{bits},y}]],Flatten[{{bits},y}[[Ordering[{{bits},y}]]]]],label=tools`stylizedRepData[rep]},Set[tools`drawTensor[out],Row@(tools`graphicalTrR[label[[4]],#]&/@{{bits},y})];Set[tools`stylizedTensor[out],tools`stylizedTr[{label[[4]],label[[3]]},{bits},y]];out];
repTrace[rep_SparseArray,{{bits___Integer},y___List},True]:=Module[{repDual,algebra=representationAlgebra[rep],out,label=tools`stylizedRepData[rep]},repDual=Transpose[tensorContract[{rep,killingMetricInverse[algebra]},{2,4}],{3,1,2}];out=Transpose[repTrace[repDual,Length/@Sort[{{bits},y}]],Flatten[{{bits},y}[[Ordering[{{bits},y}]]]]];Set[tools`drawTensor[out],Row@(tools`graphicalTrR[label[[4]],#,True]&/@{{bits},y})];Set[tools`stylizedTensor[out],tools`stylizedTr[{label[[4]],label[[3]],True},{bits},y]];out];


(* ::Section:: *)
(*Colour Tensors Related to Scattering Amplitudes for Arbitrary Gauge Groups*)


(* ::Subsection:: *)
(*All-Adjoint Scattering: (Multi-)Traces*)


singleTraceTensors[littleN_Integer]/;littleN>=2:=trR[{1,##}]&@@@Permutations[Range[2,littleN]];
multiTraceTensors[littleN_Integer]/;littleN>=2:=multiTraceTensors[littleN]=DeleteDuplicates[(Sort[PermutationCycles/@Select[Permutations[Range[littleN]],Count[Transpose[{#,Range[littleN]}],{x_,x_}]==0&]]/.Cycles[{a__}]:>trR[a])];

(*traces over the generators of real representations are dihedrally symmetric, these inlcude only dihedral equivalence class generators*)
realSingleTraceTensors[littleN_Integer]/;littleN>=2:=trR[{1,##}]&@@@Select[Permutations[Range[2,littleN]],OrderedQ[#[[{1,-1}]]]&];
realMultiTraceTensors[littleN_Integer]/;littleN>=2:=realMultiTraceTensors[littleN]=Select[multiTraceTensors[littleN],And@@(OrderedQ[#[[{2,-1}]]]&/@#)&];


(*same as above, but using trAd---which is necessarily real*)
adjointMultiTraceTensors[littleN_Integer]/;littleN>=4:=realMultiTraceTensors[littleN]/.trR->trAd;

(*tree amplitude expansion into trF or trR objects---*using* dihedral symmetry of partial amplitudes and taking dynkinIndex[F]=1
By default, the second argument is taken to be True, using trF objects---making using of the dihedral symmetry of partial amplitudes and our convention that dynkinIndex[R]=1;
If the optional second argument is specified as False, then trR objects are used, requiring an overal scaling of 1/(dynkinIndex[R]); 
The optional third argument, if set to True, then dihedral symmetry of trace tensors *VALID ONLY FOR REAL REPRESENTATIONS* is also used.
*)
treeAmpTraceExpansion[n_Integer,fundamentalRepQ_:True,realRepQ_:False]:=If[TrueQ[fundamentalRepQ],treeAmpTraceExpansion[n,fundamentalRepQ,realRepQ]=If[TrueQ[realRepQ],2Total[amp[1,##](trF[{1,##}])&@@@Select[Permutations[Range[2,n]],OrderedQ[#[[{1,-1}]]]&]],Total[amp[1,##](trF[{1,##}]+Power[-1,n]trF[{1,Sequence@@Reverse[{##}]}])&@@@Select[Permutations[Range[2,n]],OrderedQ[#[[{1,-1}]]]&]]],1/dynkinIndex[R] (treeAmpTraceExpansion[n,True,realRepQ]/.{trF->trR})];


(* ::Subsection:: *)
(*All-Adjoint Scattering: DDM ('f-graphs')*)


ddmTreeAmpTensors[littleN_Integer]/;littleN>=4:=ddmTreeAmpTensors[littleN]=ddmTensor[1,##,littleN]&@@@Permutations[Range[2,littleN-1]];
ddmTreeAmpTensors[littleN_Integer,{a_Integer,b_Integer}]/;littleN>=4&&a!=b&&Min[{a,b}]>=1&&Max[{a,b}]<=littleN:=ddmTreeAmpTensors[littleN,{a,b}]=ddmTensor[a,##,b]&@@@Permutations[Complement[Range[littleN],{a,b}]];

(*n-adjoint tree amplitudes expressed in terms of DDM tree-amp tensors*)
treeAmpDDMExpansion[n_Integer]:=treeAmpDDMExpansion[n]=Total[amp[1,##,n]ddmTensor[1,##,n]&@@@Permutations[Range[2,n-1]]];
treeAmpDDMExpansion[n_Integer,{a_Integer,b_Integer}]/;1<=Min[{a,b}]<Max[{a,b}]<=n:=treeAmpDDMExpansion[n,{a,b}]=Total[amp[a,##,b]ddmTensor[a,##,b]&@@@Permutations[Complement[Range[n],{a,b}]]];


(* ::Subsection:: *)
(*(Generic) Relations among Colour Tensors and Partial Amplitudes*)


(*decomposition of any ddmTensor[] objects appearing in exprn into tensors of the form ddmTensor[1,...,n]*)
jacobiReduce[exprn_]:=Module[{tensors=DeleteDuplicates@Cases[exprn,ddmTensor[__],{0,\[Infinity]}],images,one,n,rule},If[Length[tensors]==0,exprn,(n=Length[List@@First[tensors]];jacobiReduce[{1,n},exprn])]];
(*decomposition of any ddmTensor[] objects appearing in exprn into tensors of the form ddmTensor[x,...,y]*)
jacobiReduce[{x_Integer,y_Integer},exprn_]:=Module[{tensors=DeleteDuplicates@Cases[exprn,ddmTensor[__],{0,\[Infinity]}],images,one,len,n,rule},If[Length[tensors]==0,exprn,(len=Length[List@@First[tensors]];{one,n}=Mod[{x,y},len,1];If[SameQ[one,n],exprn,(images=tensors/.{ddmTensor[a___,one,b___]:>Which[Length[{b}]==0,Power[-1,len]ddmTensor@@Reverse[{a,one,b}],Length[{b}]==1,Power[-1,len-1]ddmTensor@@Reverse[{a,b,one}],Length[{a}]==1,-ddmTensor[one,a,b],Length[{b}]<Length[{a}],Power[-1,len]ddmTensor@@Reverse[{a,one,b}],True,ddmTensor[a,one,b]]}//.{ddmTensor[X___Integer,a_Integer,one,Y___Integer]:>If[Length[{X}]==0,-ddmTensor[one,a,Y],(*If[Length[{Y}]==1,-1,1]*)(ddmTensor[X,one,a,Y]-Power[-1,Length[{X}]]ddmTensor[one,a,Reverse@{X},Y])],ddmTensor[q___Integer,{},r___Integer]:>ddmTensor[q,r],ddmTensor[q___Integer,{s_},r___Integer]:>ddmTensor[q,s,r],ddmTensor[q___Integer,{s_,t_},r___Integer]:>ddmTensor[q,s,t,r]-ddmTensor[q,t,s,r],ddmTensor[q___Integer,{s_,t__},r___Integer]:>ddmTensor[q,s,{t},r]-ddmTensor[q,{t},s,r]}//.{ddmTensor[X___Integer,n,a_Integer,Y___Integer]:>If[Length[{Y}]==0,-ddmTensor[X,a,n],(ddmTensor[X,a,n,Y]-Power[-1,Length[{Y}]]ddmTensor[X,Reverse@{Y},a,n])],ddmTensor[q___Integer,{},r___Integer]:>ddmTensor[q,r],ddmTensor[q___Integer,{s_},r___Integer]:>ddmTensor[q,s,r],ddmTensor[q___Integer,{s_,t_},r___Integer]:>ddmTensor[q,s,t,r]-ddmTensor[q,t,s,r],ddmTensor[q___Integer,{s__,t_},r___Integer]:>ddmTensor[q,{s},t,r]-ddmTensor[q,t,{s},r]};rule=Association[Thread[Rule[tensors,images]]];exprn/.rule)])]];

(*decomposition of partial amps into those of the form amp[1,...,n]*)
kkReduce[exprn_]:=Module[{amps=DeleteDuplicates@Cases[exprn,amp[__],{0,\[Infinity]}],images,one,n,rule},If[Length[amps]==0,exprn,(n=Length[List@@First[amps]];kkReduce[{1,n},exprn])]];
(*decomposition of partial amps into those of the form amp[x,...,y]*)
kkReduce[{x_Integer,y_Integer},exprn_]:=Module[{amps=DeleteDuplicates@Cases[exprn,amp[__],{0,\[Infinity]}],images,one,n,rule},If[Length[amps]==0,exprn,(n=Length[List@@First[amps]];{one,n}=Mod[{x,y},n,1];images=(amps/.amp[a___,one,b___]:>amp[one,b,a])/.amp[one,a___,n,b___]:>Power[-1,Length[{b}]]Total[amp[one,##,n]&@@@shuffle[{a},Reverse[{b}]]];rule=Association[Thread[Rule[amps,images]]];exprn/.rule)]];

(*expansion of ddmTensor[]'s into single-trace trF[] objects*)
ddmToTrace[fundamentalRepQ_:True,exprn_]:=Module[{rule,images,tensors=DeleteDuplicates@Cases[exprn,ddmTensor[__],{0,\[Infinity]}],out},If[Length[tensors]==0,exprn,(images=tools`ddmToTrace@@@tensors;rule=Association[Thread[Rule[tensors,images]]];out=(exprn/.rule);If[Not[TrueQ[fundamentalRepQ]],1/dynkinIndex[R](out/.{trF->trR}),out])]];


(* ::Subsection:: *)
(*Arbitrarily-Charged Gauge/Matter Tree-Level Amplitudes in Arbitrary Gauge Theories *)


(*These are tensors for the case of *indistinguishable* charged fermions*)
fermionicTreeAmpTensors[nFermions_Integer,nGluons_Integer:0]:=Module[{seed=tools`fermionicTreeAmpTensorsDistinct[nFermions,nGluons],permutations=Thread[Rule[fb/@Range[nFermions],#]]&/@Permutations[fb/@Range[nFermions]]},Join@@(seed/.permutations)];


(* ::Subsubsection::Closed:: *)
(*Backend:*)


tools`traceSeedList[n_Integer]/;n>=2:=trR@@@Function[{part},Range[part[[#]]]+Total[part[[1;;#-1]]]&/@Range[Length[part]]]/@Reverse[Reverse/@Select[IntegerPartitions[n],Min[#]>=2&]];

tools`ddmToTrace[3]=trF[{1,2,3}]-trF[{1,3,2}];
tools`ddmToTrace[n_Integer]:=tools`ddmToTrace[n]=#1-#2&@@(tools`ddmToTrace[n-1]/.{{trF[x__]:>trF@@({x}/.(n-1->Sequence@@{n-1,n}))},{trF[x__]:>trF@@({x}/.(n-1->Sequence@@{n,n-1}))}});
tools`ddmToTrace[first_Integer,rest__Integer]:=tools`ddmToTrace[Length[{rest}]+1]/.trF[x_]:>trF@@({x}/.Thread[Rule[Range[Length[{rest}]+1],{first,rest}]])/.trF[{x__Integer}]:>trF@(Partition[{x},Length[{x}],1,1][[First[Ordering[{x}]]]]);

tools`dyckStrings[0]={""};tools`dyckStrings[1]={"ab"};tools`dyckStrings[n_Integer]/;n>1:=tools`dyckStrings[n]=DeleteDuplicates[Join@@StringReplaceList[tools`dyckStrings[n-1],{"ab"->"aabb","ab"->"abab"}]];tools`dyckPairs[k_Integer]/;k>=1:=tools`dyckPairs[k]=Module[{dyck=Characters[tools`dyckStrings[k]],qLabels,ords,places},places=GatherBy[Transpose[{Range[2k],#}],Last][[All,All,1]]&/@dyck;places=Function[{a,b},Ordering[Join@@{a[[Ordering[Function[{no},no-Length[Select[b,#<a[[no]]&]]]/@Range[k]]]],b[[Ordering[Function[{no},Length[Select[a,#<b[[no]]&]]-no-1]/@Range[k]]]]}]]@@@places;(Join@@Transpose[Partition[Range[2k],2]])[[#]]&/@places];
tools`fermionicTreeAmpTensorsDistinct[nFermions_Integer,nGluons_Integer:0]/;(nGluons>=0&&(2nFermions+nGluons)>=4):=tools`fermionicTreeAmpTensorsDistinct[nFermions,nGluons]=Which[nGluons==0,Module[{args,pairs=tools`dyckPairs[nFermions-1],qList,qPerms=Join@@@Permutations[{f[#],fb[#]}&/@Range[2,nFermions]]},qList=#1[[#2]]&@@@(Tuples[{qPerms,pairs}]);args={f[1],##,fb[1]}&@@@qList;joTensor@@@({#,Partition[Ordering[#[[All,1]]][[1;;2nFermions]],2]}&/@args)],nFermions==0,ddmTensor[1,##,nGluons]&@@@Permutations[Range[2,nGluons]],nFermions==1,(joTensor[{f[1],##,fb[1]},{{1,nGluons+2}}]&@@@Permutations[g/@(Range[nGluons]+1)]),True,Module[{args,pairs=tools`dyckPairs[nFermions-1],gPerms=Permutations[g/@(Range[nGluons]+nFermions)],qList,qPerms=Join@@@Permutations[{f[#],fb[#]}&/@Range[2,nFermions]]},qList=#1[[#2]]&@@@(Tuples[{qPerms,pairs}]);args={f[1],##,fb[1]}&@@@Join@@(shuffle@@@Tuples[{gPerms,qList}]);joTensor@@@({#,Partition[Ordering[#[[All,1]]][[1;;2nFermions]],2]}&/@args)]];


(* ::Section:: *)
(*Clebsch-Gordon Colour Tensors (and Bases) for a[1] Gauge Theory*)


(* ::Subsection:: *)
(*Collections of Clebsch Colour Tensor Bases in a[1] Gauge Theory*)


(*basis of a1 Clebsch colour tensors involving n external adjoints*)
a1ClebschBasis[littleN_Integer]/;littleN>=3:=a1ClebschBasis[littleN]=clebschTensor@@@(tools`a1ClebschTensorsVertexList[littleN][[All,2;;-1,1]]);
(*basis of a1 Clebsch colour tensors involving n external adjoints for which the external legs have been permuted by {legOrder}*)
a1ClebschBasis[littleN_Integer,{legOrder__Integer}]/;Length[{legOrder}]==littleN>=3&&Sort[{legOrder}]===Range[Length[{legOrder}]]:=a1ClebschBasis[littleN]/.clebschTensor[x___]:>clebschTensor[x,{legOrder}];

(*Clebsch colour bases for arbitrary collections of charged particles in a[1] gauge theory
---particles assigned weights according to {weightList}*)
a1ClebschBasis[{weightList__Integer}]/;Length[{weightList}]>=4:=If[DeleteDuplicates[Sign[{weightList}]]=={1},a1ClebschBasis[{weightList}]=clebschTensor[##,{weightList}]&@@@(tools`clebschLists[weightList]),Module[{signs=Sign/@{weightList}},a1ClebschBasis[Abs[{weightList}]]/.clebschTensor[w__Integer,{wts__Integer}]:>clebschTensor[w,(signs*{wts})]]];

(*Clebsch colour bases for arbitrary collections of charged particles in a[1] gauge theory
---particles assigned weights according to {weightList} for particles 1,...,n, 
but for which the tree has been labelled with leaves arranged according to some permutation of [n] given by {legOrder}*)
a1ClebschBasis[{weightList__Integer},{legOrder__Integer}]/;Length[{legOrder}]==Length[{weightList}]>=3&&Sort[{legOrder}]==Range[Length[{legOrder}]]:=a1ClebschBasis[{weightList},{legOrder}]=clebschTensor[##,{weightList}[[{legOrder}]],{legOrder}]&@@@(tools`clebschLists[Sequence@@Abs[{weightList}][[{legOrder}]]])


(* ::Subsection:: *)
(*Relations Between Colour Tensors in a[1] Gauge Theory*)


a1TraceTensorToClebschCoefficients[n_Integer]:=a1TraceTensorToClebschCoefficients[n]=Module[{t0=AbsoluteTime[],basis=tools`a1AdjointClebschBasis[n],trBasis,out},trBasis=tools`a1TraceTensorsDual[n];out=Transpose[tensorContract[{basis,trBasis},Transpose[{Range[n]+1,Range[n]+n+2}]]] . SparseArray[DiagonalMatrix[1/tools`a1AdjointClebschBasisScaling[n]]];If[AbsoluteTime[]-t0>1,Print["Computation of Trace-to-Clebsch coefficients for ",n," adjoints of a[1] required ",niceTime[AbsoluteTime[]-t0]]];out];

a1TraceTensorEliminationRules[n_Integer]:=a1TraceTensorEliminationRules[n]=Module[{relations=tools`a1TraceToTraceData[n],symb=trF@@@realMultiTraceTensors[n],indep,t0=AbsoluteTime[],out,elim},indep=Join@@Select[GatherBy[List@@@(ArrayRules[relations][[1;;-2,1]]),Last[#]&],Length[#]==1&][[All,All,2]];elim=Complement[Range[Length[relations[[1]]]],indep];out=Rule@@@Transpose[{symb[[elim]],Transpose[relations][[elim]] . symb[[indep]]}];If[AbsoluteTime[]-t0>1,Print["Finding all elimination rules for Trace tensors with ",n," adjoints required ",niceTime[AbsoluteTime[]-t0]]];out];


a1ddmTensorToClebschCoefficients[n_Integer]:=a1ddmTensorToClebschCoefficients[n]=Module[{t0=AbsoluteTime[],basis=tools`a1AdjointClebschBasis[n],ddmBasis,out},ddmBasis=tools`a1DDMtensorsDual[n];out=Transpose[tensorContract[{basis,ddmBasis},Transpose[{Range[n]+1,Range[n]+n+2}]]] . SparseArray[DiagonalMatrix[1/tools`a1AdjointClebschBasisScaling[n]]];If[AbsoluteTime[]-t0>1,Print["Computation of DDM-to-Clebsch coefficients for ",n," adjoints required ",niceTime[AbsoluteTime[]-t0]]];out];

a1ddmTensorEliminationRules[n_]:=a1ddmTensorEliminationRules[n]=Module[{relations=tools`a1DDMtoDDMdata[n],symb=ddmTensor[1,##,n]&@@@Permutations[Range[2,n-1]],indep,t0=AbsoluteTime[],out,elim},indep=Join@@Select[GatherBy[List@@@(ArrayRules[relations][[1;;-2,1]]),Last[#]&],Length[#]==1&][[All,All,2]];elim=Complement[Range[Length[relations[[1]]]],indep];If[Length[elim]===0,out={},out=Rule@@@Transpose[{symb[[elim]],Transpose[relations][[elim]] . symb[[indep]]}]];If[AbsoluteTime[]-t0>1,Print["Finding all elimination rules for DDM tensors with ",n," adjoints of a[1] required ",niceTime[AbsoluteTime[]-t0]]];out];


(* ::Subsubsection::Closed:: *)
(*Backend:*)


tools`riordanWords[1]={""};tools`riordanWords[2]={"aabb"};tools`riordanWords[n_]:=tools`riordanWords[n]=DeleteDuplicates[Join@@StringReplaceList[tools`riordanWords[n-1],{"ab"->"abab","abab"->"aaabbb","aaba"->"aabbaa"}]];
tools`a1ClebschTensorsSequences[n_Integer]:=tools`a1ClebschTensorsSequences[n]=Function[{list},Total[list[[1;;#-1]]]+1+list[[#]]&/@Range[2,Length[list]-2]]/@(Characters[StringReplace[StringReplace[tools`riordanWords[n],{"ab"->"p","aa"->"pp","ba"->"c","bb"->"mm"}],{"pp"->"p","mm"->"m"}]][[All,1;;-1]]/.{"p"->1,"c"->0,"m"->-1});
