(*Computing Colour-Space Overlaps Among Sets of Colour Tensors Tensors*)


contractTensors[arg_][tensorListA_List,tensorListB_List]:=Module[{parsed=tools`parseTensorList[Join[tensorListA,tensorListB]],out,groups,lens,dims,bad},parsed={parsed[[1;;Length[tensorListA]]],parsed[[Length[tensorListA]+1;;-1]]};groups=List[buildTensorsDual[arg][parsed[[1]]],buildTensors[arg][parsed[[2]]]];out=Which[Not[And@@((Head[#]===SparseArray)&/@(Join@@groups))],Print["   Not all tensors can be built for ",nice[arg],"; a particular representation must be specified to build, e.g. ",Select[groups,Not[Head[#]===SparseArray&],1][[1]]];parsed,Not[SameQ@@(Dimensions/@(Join@@groups))],(bad=GatherBy[Transpose[{Range[Length[Join@@parsed]],groups}],Dimensions[#[[2]]]&][[All,1,2]];Print["   Tensors under consideration have incompatible shapes.\n   ","    In particular, tensors ",Row[Riffle[nice[bad],", "]]," are not compatible."];parsed),ByteCount[First[groups]]<5 Power[10,5],(groups=SparseArray/@groups;lens=(Length[Dimensions[#]]-1)&/@groups;tensorContract[groups,Transpose[{Range[lens[[1]]]+1,Range[lens[[2]]]+lens[[1]]+2}]]),True,(groups={SparseArray[groups[[1]]],groups[[2]]};lens=(Length[Dimensions[#]]-1)&/@groups;SparseArray[(tensorContract[{groups[[1]],#},Transpose[Partition[Range[2lens[[1]]]+1,lens[[1]]]]]&/@groups[[2]])])];out];contractTensors[arg_][tensorA_,tensorListB_List]/;Not[Head[tensorA]===List]:=(List@@(contractTensors[arg][{tensorA},tensorListB][[1]]));contractTensors[arg_][tensorListA_List,tensorB_]/;Not[Head[tensorB]===List]:=List@@(contractTensors[arg][tensorListA,{tensorB}][[All,1]]);contractTensors[arg_][tensorA_,tensorB_]/;Not[Head[tensorA]===List]&&Not[Head[tensorB]===List]:=(contractTensors[arg][{tensorA},{tensorB}][[1,1]]);


tensorOverlap[arg_][tensorList__List]:=tensorOverlap[arg][tensorList]=Module[{parsed=tools`parseTensorList[Flatten[{tensorList}]],groups,len,dims,bad},groups=buildTensors[arg][parsed];If[And@@((Head[#]===SparseArray)&/@groups),If[SameQ@@(Dimensions/@groups),If[ByteCount[First[groups]]<5 Power[10,5],(groups={SparseArray@buildTensorsDual[arg][parsed],SparseArray@groups};len=Length[Dimensions[First[groups]]]-1;tensorContract[groups,Transpose[{Range[len]+1,Range[len]+len+2}]]),(groups={SparseArray@buildTensorsDual[arg][parsed],groups};len=Length[Dimensions[First[groups]]]-1;SparseArray[(tensorContract[{groups[[1]],#},Transpose[Partition[Range[2len]+1,len]]]&/@groups[[2]])])],bad=GatherBy[Transpose[{Range[Length[parsed]],groups}],Dimensions[#[[2]]]&][[All,1,2]];Print["   Tensors under consideration have incompatible shapes.\n   ","    In particular, tensors ",Row[Riffle[nice[bad],", "]]," are not compatible."];parsed],Print["   Not all tensors can be built for ",nice[arg],"; a particular representation must be specified to build, e.g. ",Select[groups,Not[Head[#]===SparseArray&],1][[1]]];Flatten[{tensorList}]]];

