(* ::Subsection:: *)
(*Clebsch-Gordon Tensors for a[1] Gauge Theory*)


a1Clebsch[w1_Integer,w2_Integer,w3_Integer]:=Module[{out=Which[(*If not satisfying triangle rule*)Not[MemberQ[Abs[Abs[w2]-Abs[w1]]+2Range[0,Min[Abs@{w1,w2}]],Abs@w3]]||(Count[{w1,w2,w3},0]==2),SparseArray[{},Abs[{w1,w2,w3}]+1],(*If negatives*)w1<0,dot[-tools`a1RepresentationMetricInv[-w1],a1Clebsch[-w1,w2,w3]],w2<0,Transpose[dot[-tools`a1RepresentationMetricInv[Abs@w2],a1Clebsch[-w2,w3,w1]],{2,3,1}],w3<0,Transpose[dot[-tools`a1RepresentationMetricInv[-w3],a1Clebsch[-w3,w1,w2]],{3,1,2}],(*Now they are all non-negative...*)(*If not canonically ordered arguments*)Not[First[Ordering[Partition[{w1,w2,w3},3,1,1]]]===1],Transpose[a1Clebsch@@(First[Sort[Partition[{w1,w2,w3},3,1,1]]]),Partition[Range[3],3,1,1][[First[Ordering[Partition[{w1,w2,w3},3,1,1]]]]]],(*So they are now canonically (cyclically) ordered, *)(*If they are all distinct but not actually ordered*)(w1<w2&&w3<w2),Transpose[-a1Clebsch[w1,w3,w2],{1,3,2}],(*Now, all arguments are (ordered and distinct---abc) or at least cyclically ordered (so abb,aab,aaa)*)True,(*Save results to memory---basically only for non-trivial cases*)Set[a1Clebsch[w1,w2,w3],Which[(*metrics*)w1==0&&(w2==w3),TensorProduct[SparseArray[{x_}:>1,{1}],tools`a1RepresentationMetric[w2]],(*rep tensors*)(w1==2&&w2==w3),Transpose[dot[(*-*)a1Rep[w2],tools`a1RepresentationMetric[w2]],{3,1,2}],(w3==2&&w1==w2==1),Transpose[dot[(*-*)a1Rep[w2],tools`a1RepresentationMetric[w2]],{2,3,1}],(*special case hard-coded for adjoint related clebsches*)w1==2&&(w2==(w3-2)),(*If[EvenQ[w2],-w2/2-1,-(2+w2)]*)dot[Transpose[SparseArray[SparseArray[Band[{#+1,1}]->{1,Power[-1,(w2-1) (#+1)+1],Power[-1,w2]},{w2+3,3}]&/@Range[0,w2]],{2,3,1}],tools`a1RepresentationMetric[w3]],(*general case\[LongDash]requiring some work*)True,Module[{prod=productRep[a1Rep[w2],a1Rep[w3]],c2,imgRange,pros,sims,active},c2=tensorContract[{prod,prod,tools`a1RepresentationMetricInv[2]},{{3,4},{2,7},{5,8}}];imgRange=w3-w2+(2Range[0,w2]);active=Select[Range[w2+1],If[MemberQ[{0,2}+w2,w3],2<imgRange[[#]],True]&&(imgRange[[#]]<=w2)&];pros=(Times@@@Transpose[{Times@@((1/(#[[1]]-#[[2;;-1]])))&/@Partition[# (#+2)/2&/@imgRange,1+w2,1,1],RotateLeft[dot@@@Partition[(SparseArray[c2-SparseArray[{x_,x_}:># (#+2)/2,{1,1}*(w2+1)(w3+1)]]&/@(imgRange)),w2,1,1],1]}])[[active]];imgRange=imgRange[[active]];pros=Function[{projector},Module[{indepR=tools`independentRows[projector],r},r=projector[[indepR]];{r,dot[projector,Transpose[r],SparseArray[inverse[dot[r,Transpose[r]]]]]}]]/@pros;sims=If[#2===SparseArray[{},{1,3,1}],SparseArray[{x_,x_}:>1,Dimensions[#1][[{1,-1}]]],findSimilarity[#1,#2]]&@@@(Transpose[{dot[#1,prod,#2]&@@@pros,a1Rep/@(imgRange)}]);Set[a1Clebsch[#1,w2,w3],Transpose[#2,{2,3,1}]]&@@@Transpose[{imgRange,(Partition[#,w3+1]&/@(dot@@@Transpose[{pros[[All,-1]],sims,(tools`a1RepresentationMetric/@imgRange)}]))}];a1Clebsch[w1,w2,w3]]]]]},Set[tools`stylizedTensor[out],tools`stylizedClebsch@@(If[#<0,wc[a][-#],w[a][#]]&/@{w1,w2,w3})];Set[tools`drawTensor[out],tools`graphicalClebsch@@(If[#<0,wc[a][-#],w[a][#]]&/@{w1,w2,w3})];out];


