(*ddmTensor objects*)
tools`ddmTensor[alg_,{order__Integer}]/;tools`legalAlgebraTrueQ[alg]:=tools`ddmTensor[alg,{order}]=Module[{out,n=Length[{order}],flips=(Flatten[Position[Sign/@{order},-1]])},out=Power[-1,Length[flips]]Transpose[tensorContract[Join[{dotPower[adjointRep[alg],n-2],killingMetric[alg]},killingMetricInverse[alg]&/@Range[Length[flips]]],Prepend[Transpose[{(flips/.{n->n+2}),2Range[Length[flips]]+n+2}],{n,n+1}]],Abs[{order}][[Join[Complement[Range[n],flips],flips]]]];Set[tools`stylizedTensor[out],tools`stylizedDDMTensor[{order},alg]];Set[tools`drawTensor[out],tools`graphicalDotPower[adjointDynkinLabel[alg],Length[{order}],{order},True]];out];

(*joTensor objects*)
