tools`joTensor[rep_SparseArray,labelList_List,flavourPairingsIn_List]:=tools`joTensor[rep,labelList,flavourPairingsIn]=Module[{n=Length[labelList],k=Length[flavourPairingsIn],slices,pairings,nestings,contracts,flavourPairings=Sort[flavourPairingsIn],out},pairings=SortBy[Join[flavourPairings,Partition[Complement[Range[Length[labelList]],Join@@flavourPairings],1]],(First[Sort@Mod[#-flavourPairings[[1,2]],Length[labelList],1]])&];nestings=Function[{pair},{Select[Complement[DeleteCases[pairings,{x_}],{pair}],Length[Intersection[Mod[Range@@(If[Not[OrderedQ[#]],#+{0,n},#]&@Mod[#-flavourPairings[[1,2]],n,1]),n,1],Mod[pair-flavourPairings[[1,2]],n,1]]]==Length[pair]&],pair}]/@pairings[[2;;-1]];nestings=(nestings/.Thread[Rule[DeleteCases[pairings,{q_}],Range[Length[DeleteCases[pairings,{q_}]]]]]);slices=Function[{slices,head},If[Head[head]===List,tools`sliceTensor[rep,k,slices,g],tools`sliceTensor[rep,k,slices,head]]]@@@nestings;contracts=2k+If[Length[pairings[[#]]]==2,0,1]&/@Range[2,Length[pairings]];contracts=(Range[contracts[[#]]]+Total[contracts[[1;;#-1]]])[[Join[Range[k],-Reverse[Range[k]]]]]&/@Range[Length[contracts]];contracts=Join@@(Transpose[{#1[[2]],#2[[1]]}]&@@@(Partition[Partition[#,k]&/@contracts,2,1]));out=Transpose[tensorContract[slices,contracts],Join[Cases[labelList[[Flatten@Cases[pairings,{x_,y_}]]],f[x_]:>x],labelList[[Cases[pairings,{x_}][[All,1]],1]],Cases[labelList[[Flatten@Cases[pairings,{x_,y_}]]],fb[x_]:>(n+1-x)]]];Set[tools`stylizedTensor[out],tools`stylizedJOtensor[labelList,flavourPairingsIn,False,rep]];Set[tools`drawTensor[out],tools`graphicalJOtensor[labelList,flavourPairingsIn,False,rep]];out];
tools`joTensorDual[rep_SparseArray,labelList_List,flavourPairings_List]:=tools`joTensorDual[rep,labelList,flavourPairings]=Module[{gs=labelList[[Complement[Range[Length[labelList]],Flatten[flavourPairings]],1]],algebra=representationAlgebra[rep],nF=Length[flavourPairings],out},out=If[Length[gs]==0,Transpose[tools`joTensor[rep,labelList,flavourPairings],Reverse[Range[Length[labelList]]]],Transpose[tensorContract[Join[{tools`joTensor[rep,labelList,flavourPairings]},killingMetricInverse[algebra]&/@Range[Length[gs]]],Transpose[{gs,2Range[Length[gs]]+Length[labelList]}]],Join[Reverse[Range[nF]+nF+Length@gs],Reverse[Range[nF]],gs]]];Set[tools`stylizedTensor[out],tools`stylizedJOtensor[labelList,flavourPairings,True,rep]];Set[tools`drawTensor[out],tools`graphicalJOtensor[labelList,flavourPairings,True,rep]];out];

(*clebschTensors for a[1] gauge theory*)
tools`clebschTensor[weightList__Integer,{repWeights__Integer},{legOrder___Integer}]/;(Length[{repWeights}]==Length[{legOrder}]==(Length[{weightList}]+3))&&(Sort[{legOrder}]===Range[Length[{legOrder}]]):=tools`clebschTensor[weightList,{repWeights},{legOrder}]=Module[{out=If[Not[OrderedQ[{legOrder}]]&&Length[DeleteDuplicates[{repWeights}]]==1,Transpose[tools`clebschTensor[weightList,{repWeights},Range[Length[{repWeights}]]],{legOrder}],tools`clebschTensor[weightList,{repWeights},{legOrder}]=Module[{n=Length[{weightList}]+3,clebsches},clebsches=(a1Clebsch@@@({#1[[1]],#2,-#1[[2]]}&@@@(Transpose[{Partition[RotateLeft[Join[{-1,1}*{repWeights}[[{-1,1}]],{weightList}]],2,1],{repWeights}[[2;;-2]]}])));Transpose[tensorContract[clebsches,Join@@({Last[#1],First[#2]}&@@@#&/@(Partition[#,2,1]&/@Partition[Partition[Range[(3n-6)],3],n-2]))],{legOrder}]]]},Set[tools`stylizedTensor[out],tools`stylizedClebsch[weightList,{repWeights},{legOrder}]];Set[tools`drawTensor[out],tools`graphicalClebsch[weightList,{repWeights},{legOrder}]];out];
