(*checking compatibility---and modifying input accordingly if obvious tweak exists*)
tools`parseTensorList[tensorList_List]:=Module[{types=Cases[tensorList,#,{0,\[Infinity]}]&/@{joTensor[__],ddmTensor[__],clebschTensor[__],trR[__],trF[__],trAd[__]},parsed},Which[Length[types[[1]]]>0,Module[{nF,n,rules},{n,nF}=List@@Length/@First[First[types]];rules=Thread[Rule[#,-#]]&@(Range[nF]+n-nF);parsed=(tensorList/.{ddmTensor[x__]:>ddmTensor@@({x}/.rules),clebschTensor[weights__Integer]:>clebschTensor[weights,Join[2&/@Range[(Length[{weights}]+3)-nF],-2&/@Range[nF]](*,Range[Length[{weights}]+3]*)],clebschTensor[weights__Integer,{perm__Integer}]:>If[Sort[{perm}]===Range[Length[{perm}]],clebschTensor[weights,Join[2&/@Range[(Length[{weights}]+3)-nF],-2&/@Range[nF]],{perm}],clebschTensor[weights,{perm}]],clebschTensor[weights__Integer,{extWeights__Integer},{perm__Integer}]:>clebschTensor[weights,Join[Abs@{weights}[[Range[(Length[{weights}]+3)-nF]]],-Abs@{weights}[[Range[nF]+n-nF]]],{perm}]});If[Max[Length/@types[[-3;;-1]]]>0,Print["   ",Style["joTensor[] ",Bold],"tensors and ",Style["tr[] ",Bold]," tensors have incompatible types."]];parsed],True,tensorList]/.{trF[x__Integer]:>trF[{x}],trR[x__Integer]:>trR[{x}],trAd[x__]:>trAd[{x}]}];


(* ::Subsubsection:: *)
(*Backend: Explicit Colour Tensors for a[1] Gauge Theory*)


tools`a1RepresentationMetricInv[w_Integer]/;w>=0:=tools`a1RepresentationMetricInv[w]=SparseArray[{#,w+2-#}->(Power[-1,(#)w]Binomial[w,#-1])&/@Range[w+1]];
tools`a1RepresentationMetric[w_Integer]/;w>=0:=tools`a1RepresentationMetric[w]=inverse[tools`a1RepresentationMetricInv[w]];

tools`a1AdjointClebschBasis[n_Integer]:=tools`a1AdjointClebschBasis[n]=SparseArray@(buildTensors[a[1]][a1ClebschBasis[n]]);
tools`a1AdjointClebschBasisScaling[n_Integer]:=tools`a1AdjointClebschBasisScaling[n]=Abs[tensorContract[Join[a1Clebsch@@@#,a1Clebsch@@@(-#)],Join[{Last[#1],First[#2]}&@@@Partition[Partition[Range[3n-6],3],2,1],{Last[#1],First[#2]}&@@@Partition[Partition[Range[3n-6]+(3n-6),3],2,1],Transpose[{RotateLeft[Join[{3n-6,1},Partition[Range[3n-6],3][[All,2]]]],RotateLeft[Join[{6n-12,1+3n-6},Partition[Range[3n-6]+3n-6,3][[All,2]]]]}]]]&/@tools`a1ClebschTensorsVertexList[n]];

tools`a1TraceTensorsDual[n_Integer]:=tools`a1TraceTensorsDual[n]=Module[{t0=AbsoluteTime[],out},out=SparseArray@buildTensorsDual[fundamentalRep[a[1]]][realMultiTraceTensors[n]];If[AbsoluteTime[]-t0>1,Print[niceTime[AbsoluteTime[]-t0]," required to construct the entire set of a[1] mutli-trace dual-tensors."];];out];

tools`a1TraceToTraceData[n_]:=tools`a1TraceToTraceData[n]=Module[{indep,coeffs=a1TraceTensorToClebschCoefficients[n],inv,out,t0=AbsoluteTime[]},indep=tools`independentRows[Reverse@coeffs,False];inv=inverse[Reverse[coeffs][[indep]]];out=Transpose@dot[coeffs,inv];If[AbsoluteTime[]-t0>1,Print["Finding all relations satisfied by multi-trace tensors for ",n," adjoints of a[1] required ",niceTime[AbsoluteTime[]-t0]]];out];


tools`a1DDMtensorsDual[n_Integer]:=tools`a1DDMtensorsDual[n]=Module[{t0=AbsoluteTime[],out},out=SparseArray@(Transpose[tensorContract[Append[-a1Clebsch[-2,-2,2]&/@Range[n-2],tools`a1RepresentationMetricInv[2]],Append[{Last[#1],First[#2]}&@@@Partition[Partition[Range[3(n-2)],3],2,1],{3n-6,3n-5}]],#]&/@({1,##,n}&@@@Permutations[Range[2,n-1]]));If[AbsoluteTime[]-t0>1,Print[niceTime[AbsoluteTime[]-t0]," required to construct the entire tree-level basis of DDM dual-tensors for a[1]."];];out];

tools`a1DDMtoDDMdata[n_Integer]:=tools`a1DDMtoDDMdata[n]=Module[{indep,t0=AbsoluteTime[],coeffs=a1ddmTensorToClebschCoefficients[n],inv,out},out=SparseArray@DeleteCases[RowReduce[Transpose[coeffs]],{0..}];If[AbsoluteTime[]-t0>1,Print["Finding all relations satisfied by DDM colour tensors for ",n," adjoints of a[1] required ",niceTime[AbsoluteTime[]-t0]]];out];


