tools`stylizedClebsch[cLabels__Integer,{extLabels__Integer},dualQ_:False]/;(Length[{extLabels}]==Length[{cLabels}]+3)&&Not[Head[dualQ]===Integer]:=If[Sort[{extLabels}]===Range[Length[{extLabels}]],tools`stylizedClebsch[cLabels,2&/@Range[Length[{extLabels}]],{extLabels},dualQ],tools`stylizedClebsch[cLabels,{extLabels},Range[Length[{extLabels}]],dualQ]];
tools`stylizedClebsch[cLabels__Integer,dualQ_:False]/;Not[Head[dualQ]===Integer]:=tools`stylizedClebsch[cLabels,2&/@Range[Length[{cLabels}]+3],Range[Length[{cLabels}]+3],dualQ];
