(*multi-trace objects*)
tools`stylizedTr[name_,x__List]/;Not[Head[name]===List]:=Module[{},Row[{Subscript[Style["tr",Black,FontFamily->"Times",FontSize->20],Magnify[tools`stylizedWeightLabel[name],0.75]],Style["[",Black,FontFamily->"Times",FontSize->20],Sequence@@Join@(Style[#,FontFamily->"Times",FontSize->18]&/@Riffle[Row[{"(",##,")"}]&@@@(Style[#,RGBColor[0.6,0.2,0.3]]&/@#&/@{x}),"|"]),Style["]",Black,FontFamily->"Times",FontSize->20]}]];
