tools`stylizedTrR[x__]:=Row[{Subscript[Style["tr",Black,FontFamily->"Times",FontSize->20],Style["R",RGBColor[0.2,0.2,0.6],FontSize->14,FontFamily->"Times",Bold]],Style["[",Black,FontFamily->"Times",FontSize->20],Sequence@@Join@(Style[#,FontFamily->"Times",FontSize->18]&/@Riffle[Row[{"(",##,")"}]&@@@(Style[#,RGBColor[0.6,0.2,0.3]]&/@#&/@{x}),"|"]),Style["]",Black,FontFamily->"Times",FontSize->20]}];
tools`stylizedTrF[x__]:=Row[{Subscript[Style["tr",Black,FontFamily->"Times",FontSize->20],Style["F",RGBColor[0.2,0.2,0.6],FontSize->14,FontFamily->"Times",Bold]],Style["[",Black,FontFamily->"Times",FontSize->20],Sequence@@Join@(Style[#,FontFamily->"Times",FontSize->18]&/@Riffle[Row[{"(",##,")"}]&@@@(Style[#,RGBColor[0.6,0.2,0.3]]&/@#&/@{x}),"|"]),Style["]",Black,FontFamily->"Times",FontSize->20]}];
