(*dot-powers of representations*)
tools`stylizedDotPower[rep_SparseArray,{orderSequence__Integer}]:=Module[{n=Length[{orderSequence}]+2,nameData=tools`stylizedRepData[rep],name},name=nameData[[4]];Module[{algebra=nameData[[3]]},Subsuperscript[Row[{Subscript[Style["\[ScriptCapitalC]",Black,FontFamily->"Times",FontSize->20],Magnify[tools`stylizeAlgebra[algebra],0.75]],Style["[",Black,FontFamily->"Times",FontSize->20],nice[name],Style[" ",FontSize->2.5],Sequence@@((Join@@((({Tooltip[Style[ToString[#],FontSize->18,FontFamily->"Times",tools`repColour[adjointDynkinLabel[algebra]],Bold],nice[adjointDynkinLabel[algebra]]],Style[" ",FontSize->5]}))&/@({orderSequence}+1)))[[1;;-2]]),Style["|",Black,Bold,FontFamily->"Times",FontSize->18],nice[name],Style["]",Black,FontFamily->"Times",FontSize->20]}],Row[{Style[" ",FontFamily->"Times",FontSize->10],Sequence@@(Join[Style["  ",FontSize->12]&/@Range[(n-1)],Style[" ",FontSize->10]&/@Range[((Floor[Log[10,First[Dimensions[rep]]]]))+(n-2)((Floor[Log[10,Dimensions[rep][[2]]]]))]]),Style["[",nameData[[-1]],Bold,FontFamily->"Times",FontSize->12],Style[First[Dimensions[rep]],nameData[[-1]],FontFamily->"Times",FontSize->12],Style["]",nameData[[-1]],Bold,FontFamily->"Times",FontSize->12]}],Row[{Style[" ",FontFamily->"Times",FontSize->10],Sequence@@{Style["[",nameData[[-1]],Bold,FontFamily->"Times",FontSize->12],Style[First[Dimensions[rep]],nameData[[-1]],FontFamily->"Times",FontSize->12],Style["]",nameData[[-1]],Bold,FontFamily->"Times",FontSize->12]},Sequence@@(Join@@({Style["[",tools`repColour[adjointDynkinLabel[algebra]],Bold,FontFamily->"Times",FontSize->12],Style[Dimensions[rep][[2]],tools`repColour[adjointDynkinLabel[algebra]],FontFamily->"Times",FontSize->12],Style["]",tools`repColour[adjointDynkinLabel[algebra]],Bold,FontFamily->"Times",FontSize->12]}&/@Range[n-2])),Style[" ",FontFamily->"Times",FontSize->10]}]]]];
