(*jo tensors*)
tools`stylizedJOtensor[stateList_List,flavourGroups_List,dualQ_:False,rep_:{}]:=Module[{repLabel=If[rep==={},{"","","","",Black},tools`stylizedRepData[rep]],n=Length[stateList],colourPairs=Transpose[{stateList[[#]]&/@flavourGroups,tools`colourList[[First@Cases[stateList[[#]],f[x_]:>x]&/@flavourGroups]]}],rules},rules=Join[Join@@(Function[{pair,col},Thread[Rule[pair,{Style[UnderBar@ToString[Cases[pair,f[_]][[1,1]]],FontFamily->"Times New Roman",FontSize->18,Bold,col],Style[OverBar@ToString[n+1-Cases[pair,fb[_]][[1,1]]],FontFamily->"Times New Roman",FontSize->18,Bold,col]}]]]@@@colourPairs),{g[x_]:>Style[ToString[x],FontFamily->"Times New Roman",Bold,FontSize->18,Black],p[x_]:>Style[Superscript[ToString[x],"+"],FontFamily->"Times New Roman",Bold,FontSize->18,Black],m[x_]:>Style[Superscript[ToString[x],"-"],FontFamily->"Times New Roman",Bold,FontSize->18,Black]}];Subsuperscript[Row[{If[rep==={},Style[If[TrueQ[dualQ],OverBar[#],#]&@"\[ScriptCapitalC]",FontFamily->"Times",FontSize->20],Subscript[Style[If[TrueQ[dualQ],OverBar[#],#]&@"\[ScriptCapitalC]",FontFamily->"Times",FontSize->20],Row[{Style[repLabel[[1]],FontSize->16,FontFamily->"Times",Bold,repLabel[[-1]]],Style["[",FontSize->16,FontFamily->"Times"],Magnify[tools`stylizeAlgebra[repLabel[[3]]],0.9],Style["]",FontSize->16,FontFamily->"Times"]}]]],Style["[",FontFamily->"Times",FontSize->20],If[TrueQ[dualQ],OverBar[#],#]&@Row@Riffle[(stateList/.rules),","],Style["]",FontFamily->"Times",FontSize->20]}],##]&@@(If[TrueQ[dualQ],Reverse[#],#]&@{Row@Join[Style["  ",FontSize->If[rep==={},5,12]]&/@Range[(n-Length[flavourGroups])],Style[" ",FontSize->10]&/@Range[If[rep==={},{},(Length[flavourGroups])((Floor[Log[10,First[Dimensions[rep]]]]))+(n-2Length[flavourGroups])((Floor[Log[10,Dimensions[rep][[2]]]]))]],If[rep==={},Style["r",#,Bold],Row[{Style["[",#,Bold,FontFamily->"Times",FontSize->12],Style[First[Dimensions[rep]],#,FontFamily->"Times",FontSize->12],Style["]",#,Bold,FontFamily->"Times",FontSize->12]}]]&/@Reverse[SortBy[colourPairs,#[[1,2]]&][[All,2]]]],Row@Join[If[rep==={},(Cases[#1,f[x_]:>Style["r",#2,Bold]][[1]]&@@@SortBy[colourPairs,First[First[#]]&]),(Cases[#1,f[x_]:>Row[{Style["[",#2,Bold,FontFamily->"Times",FontSize->12],Style[First[Dimensions[rep]],#2,FontFamily->"Times",FontSize->12],Style["]",#2,Bold,FontFamily->"Times",FontSize->12]}]][[1]]&@@@SortBy[colourPairs,First[First[#]]&])],If[Count[stateList,g[_]|p[_]|m[_]]==0,{},Join[(*{Style[" ",FontSize->6]},*)If[rep==={},Style["\[GothicG]",FontFamily->"Times",FontSize->10,Bold],Style["["<>ToString[Dimensions[rep][[2]]]<>"]",FontFamily->"Times",FontSize->12]]&/@Range[Count[stateList,g[_]|p[_]|m[_]]]]]]})];

(*ddm tensors*)
tools`stylizedDDMTensor[{order__Integer},alg_:{}]:=Module[{color=tools`repColour[w[a][1,0,1]]},Row[{If[alg==={},Style["\[ScriptF]",Bold,FontFamily->"Times New Roman",FontSize->20,color],Subscript[Style["\[ScriptF]",Bold,FontFamily->"Times New Roman",FontSize->20,color],Style[Magnify[tools`stylizeAlgebra[alg],0.75],FontSize->16,FontFamily->"Times",Bold,color]]],Style["[",FontFamily->"Times New Roman",FontSize->20],Sequence@@((Join@@({Style[If[#<0,OverBar[-#],#],FontFamily->"Times",Bold,color,FontSize->20],Style[" ",FontFamily->"Times",FontSize->6]}&/@{order}))[[1;;-2]]),Style["]",FontFamily->"Times New Roman",FontSize->20]}]];


