(* ::Subsection:: *)
(*Drawing Tensor Diagrams for Concrete and Abstract Tensor Objects*)


drawTensors[exprn_]:=(exprn/.{array_SparseArray:>Module[{test=tools`drawTensor[array]},If[Head[test]===tools`drawTensor,array,test]],joTensor[args__]:>tools`graphicalJOtensor[args],clebschTensor[args__]:>tools`graphicalClebsch[args],trR[args__]:>tools`graphicalTrR["R",args],trF[args__]:>tools`graphicalTrR[w[a][1,0,0],args],trAd[args__]:>tools`graphicalTrR[w[a][1,0,1],args],ddmTensor[args__]:>tools`graphicalDotPower[ad,Length[{args}],{args},True],dynkinIndex[R]->Row@({Style["T(",FontSize->16,FontFamily->"Times"],Style["R",FontSize->16,FontFamily->"Times",tools`repColour[w[a][1,0,0]]],Style[")",FontSize->16,FontFamily->"Times"]})}/.{Times[x_?NumericQ,y_Graphics]:>If[x===-1,-y,Row[{Style[x,FontFamily->"Times",FontSize->20],y}]]});


(* ::Subsubsection::Closed:: *)
(*Backend: Elements of Tensor Diagrams*)


(*tensor diagram nodes*)
tools`diagramVertex[pt_List,label_,size_:0.105]/;Count[label,w[a_][b___]|wc[a_][b__],{0,\[Infinity]}]>0:={EdgeForm[{tools`repColour[label]}],tools`repColour[label],Disk[pt,size]};
tools`diagramVertex[pt_List,{name_,color_},size_:0.105]:={EdgeForm[{color}],color,Disk[pt,size]};
tools`diagramVertex[pt_List,size_:0.095]/;Not[Head[size]===List]:={{EdgeForm[Black],GrayLevel[0.9],Disk[pt,size]}};

(*stylized lines encoding representations*)
tools`arcToCurvedPts[\[Theta]_,\[Delta]_]:=Module[{ell=4/3Tan[\[Delta]/4],pts},Join@@(RotationMatrix[-\[Theta]] . #&/@#&/@List[{{-1,0},{-1,ell}},{{Cos[-\[Pi]-\[Delta]],Sin[-\[Pi]-\[Delta]]}+ell{Cos[(-\[Pi]-\[Delta])+\[Pi]/2],Sin[-\[Pi]-\[Delta]+\[Pi]/2]},{Cos[-\[Pi]-\[Delta]],Sin[-\[Pi]-\[Delta]]}}])];
tools`repLine[pts_List,label_,endPt_Integer:0,labelQ_:True,reverseQ_:False,arcQ_:False]/;Count[label,w[a_][b___]|wc[a_][b___],{0,\[Infinity]}]>0:=Module[{mid,norm,color,alg,tq},alg=Cases[(label/.wc->w),w[type_][weightSequence__Integer]:>type[Length[{weightSequence}]],{0,\[Infinity]}][[1]];tq=label==w[Head[alg]]@@PadRight[{0},alg[[1]]];mid=If[TrueQ[arcQ],BezierFunction[tools`arcToCurvedPts@@pts][0.5],Mean[pts]];norm=-0.175If[TrueQ[arcQ],1.0({#2,-#1}&@@(#1-#2&@@(BezierFunction[tools`arcToCurvedPts@@pts]/@{0,1}))),0.15/0.175(Sign[#1]{#2,-#1}&@@(pts[[2]]-pts[[1]]))];color=tools`repColour[label];color=If[Head[First[#]]===tools`repColour,tools`colourList[[3]],Sequence@@#]&@{tools`repColour[label]};{AbsoluteThickness[1.75],CapForm["Round"],color,Arrowheads[{{Medium,If[TrueQ[reverseQ],0.8,If[TrueQ[arcQ],0.575,0.65]]}}],If[TrueQ[labelQ],#,Tooltip[#,Style[tools`stylizedWeightLabel[label],color]]]&@If[TrueQ[arcQ],{CapForm["Round"],Arrow[BezierCurve[tools`arcToCurvedPts@@(If[TrueQ[reverseQ],Reverse[#],#]&@pts)]]},{CapForm["Round"],If[TrueQ[tq],Line[#],Arrow[#]]&@(If[TrueQ[reverseQ],Reverse[#],#]&@pts)}],If[TrueQ[labelQ],Text[If[Count[label,w[_][__]|wc[_][__],{0,\[Infinity]}]>1,Magnify[#,0.6],#]&@tools`stylizedWeightLabel[label],mid+norm,-5norm],Nothing],Black,If[endPt===0,Nothing,Text[Style[endPt,FontSize->16,FontFamily->"Times"],pts[[2]]+1.2(pts[[1]]-pts[[2]]),-0.05(pts[[1]]-pts[[2]])]]}];
(*tools`repLine[pts_List,{name_String,col_,alg_},endPt_Integer:0,labelQ_:True,reverseQ_:False,arcQ_:False]:=Module[{mid,norm,color,tq},tq=reverseQ;mid=If[TrueQ[arcQ],BezierFunction[tools`arcToCurvedPts@@pts][0.5],Mean[pts]];norm=-0.175If[TrueQ[arcQ],1.0({#2,-#1}&@@(#1-#2&@@(BezierFunction[tools`arcToCurvedPts@@pts]/@{0,1}))),0.15/0.175(Sign[#1]{#2,-#1}&@@(pts[[2]]-pts[[1]]))];color=col;{AbsoluteThickness[1.75],CapForm["Round"],color,Arrowheads[{{Medium,If[TrueQ[reverseQ],0.8,If[TrueQ[arcQ],0.575,0.65]]}}],If[TrueQ[labelQ],#,Tooltip[#,Style[name,Bold,FontFamily->"Times",FontSize->16,color]]]&@If[TrueQ[arcQ],{CapForm["Round"],Arrow[BezierCurve[tools`arcToCurvedPts@@(If[TrueQ[reverseQ],Reverse[#],#]&@pts)]]},{CapForm["Round"],If[TrueQ[tq],Line[#],Arrow[#]]&@(If[TrueQ[reverseQ],Reverse[#],#]&@pts)}],If[TrueQ[labelQ],Text[Style[name,FontSize->16,FontFamily->"times",color],mid+norm,-5norm],Nothing],Black,If[endPt===0,Nothing,Text[Style[endPt,FontSize->16,FontFamily->"Times"],pts[[2]]+1.2(pts[[1]]-pts[[2]]),-0.05(pts[[1]]-pts[[2]])]]}];*)
tools`repLine[pts_List,{name_String,col_,alg_},endPt_Integer:0,labelQ_:True,reverseQ_:False,arcQ_:False]:=Module[{mid,norm,color,tq},tq=reverseQ;mid=If[TrueQ[arcQ],BezierFunction[tools`arcToCurvedPts@@pts][0.5],Mean[pts]];norm=-0.175If[TrueQ[arcQ],1.0({#2,-#1}&@@(#1-#2&@@(BezierFunction[tools`arcToCurvedPts@@pts]/@{0,1}))),0.15/0.175(Sign[#1]{#2,-#1}&@@(pts[[2]]-pts[[1]]))];color=col;{AbsoluteThickness[1.75],CapForm["Round"],color,Arrowheads[{{Medium,If[TrueQ[reverseQ],0.8,If[TrueQ[arcQ],0.575,0.65]]}}],If[TrueQ[labelQ],#,Tooltip[#,Style[name,Bold,FontFamily->"Times",FontSize->16,color]]]&@If[TrueQ[arcQ],{CapForm["Round"],Arrow[BezierCurve[tools`arcToCurvedPts@@(If[TrueQ[reverseQ],Reverse[#],#]&@pts)]]},{CapForm["Round"],If[TrueQ[tq],Arrow[#],Arrow[#]]&@(If[TrueQ[reverseQ],Reverse[#],#]&@pts)}],If[TrueQ[labelQ],Text[Style[name,FontSize->16,FontFamily->"times",color],mid+norm,-5norm],Nothing],Black,If[endPt===0,Nothing,Text[Style[endPt,FontSize->16,FontFamily->"Times"],pts[[2]]+1.2(pts[[1]]-pts[[2]]),-0.05(pts[[1]]-pts[[2]])]]}];

(*elements of JO tensors*)
tools`tensorColumnTemplate[slot_Integer,nRungs_Integer,isGluon_:False,startNo_:0,rep_:{}]:=Module[{rungSpacing=1/2,dx=1,gColor=RGBColor[{0.575,0,0.225}],fColor=RGBColor[{0.235,0.235,0.6}],labelDat,levels},If[Not[rep==={}],labelDat=tools`stylizedRepData[rep];fColor=Last[labelDat];];levels=Range[0,(nRungs-1+If[isGluon,1,0]) rungSpacing,rungSpacing];{AbsoluteThickness[1.4],CapForm["Round"],{gColor,tools`wavyLine[{{slot+dx/2,#1- 0.025},{slot+dx/2,#2+ 0.025}}]}&@@@Partition[levels[[Max[{startNo,1}];;-1]],2,1],fColor,{AbsoluteThickness[7],White,Line[{{slot+0.4,#},{(slot+dx-0.4),#}}]}&/@levels[[1;;If[TrueQ[isGluon],-2,-1]]],{AbsoluteThickness[1.4],Arrowheads[{{Medium,0.03}}],Arrow[{{slot,#},{(slot+dx),#}}]}&/@levels[[1;;If[TrueQ[isGluon],-2,-1]]],If[startNo===0,Sequence@@{{{GrayLevel[0.95],EdgeForm[Directive[AbsoluteThickness[1.4],fColor]],Disk[{slot+dx/2,#},0.075]}&/@levels[[1;;-2]]},{{fColor,EdgeForm[Directive[AbsoluteThickness[1.05],fColor]],Disk[{slot+dx/2,#},0.0475]}&/@levels[[If[TrueQ[isGluon],{},-1;;-1]]]}},(Join[{fColor,EdgeForm[Directive[AbsoluteThickness[1.05],fColor]],Disk[{slot+dx/2,#},0.0475]}&/@levels[[startNo;;startNo]],If[TrueQ[isGluon],{},{fColor,EdgeForm[Directive[AbsoluteThickness[1.05],fColor]],Disk[{slot+dx/2,#},0.0475]}&/@levels[[-1;;-1]]]])]}];
tools`arc[{a_List,b_List},label_Integer:0]:=If[label===0,{tools`colourList[[13]],Arrowheads[{{Medium,0.6}}],Arrow@BezierCurve[{a,.325(b+a),b}]},{tools`colourList[[label]],{Arrowheads[{{Medium,0.6}}],Tooltip[Arrow@BezierCurve[{a,.325(b+a),b}],label,TooltipStyle->{tools`colourList[[label]]}]}}];
tools`wavyLine[{x0_,y0_}]:=Module[{x=x0+(y0-x0)*0.05,y=y0+(x0-y0)*0.05,delta={-(y0-x0)[[2]],(y0-x0)[[1]]}/19,P},P=3;BSplineCurve[Evaluate[Map[(x+(y-x) #/(4P)+Sign[Mod[#,4]](Mod[#,4]-2)delta)&,Range[0,4P]]],SplineWeights->Prepend[Append[PadLeft[{},4P-1,1],1/2],1/2]]];


(* ::Subsubsection:: *)
(*Backend: Specific Diagrams for Specific Colour Tensors*)


(*(multi-)traces over representations*)
tools`graphicalTrR["R",ordering_List,dualQ_:False]/;BooleanQ[dualQ]:=tools`graphicalTrR["R",ordering,dualQ]=Module[{n=Length[ordering]},Graphics[Join@@Join[tools`repLine[#,{"R",tools`repColour[w[a][1,0,0]],a[3]},0,False,False,True]&/@({(#-1/2)2\[Pi]/n,2\[Pi]/n}&/@Range[n]),tools`repLine[{1.95{Cos[#1],Sin[#1]},{Cos[#1],Sin[#1]}},{"ad",tools`repColour[w[a][1,0,1]],a[3]},#2,False,dualQ,False]&@@@(({\[Pi]-(#-1/2)2\[Pi]/n,ordering[[#]]}&/@Range[n])),tools`diagramVertex[{Cos[#],Sin[#]},{"R",tools`repColour[w[a][1,0,0]]},0.07]&/@(\[Pi]-(#-1/2)2\[Pi]/n&/@Range[n])],ImageSize->If[n==2,80,120]]];
tools`graphicalTrR[repLabel_,ordering_List,dualQ_:False]/;Length[ordering]>=2&&Count[repLabel,w[x_][y__],{0,\[Infinity]}]>0&&BooleanQ[dualQ]:=tools`graphicalTrR[repLabel,ordering,dualQ]=Module[{alg,n=Length[ordering],label=(repLabel/.If[TrueQ[dualQ],{w[r_][s__]:>wc[r][s],wc[r_][s__]:>w[r][s]},{}])},alg=Join[Cases[repLabel,w[x_][y__]:>x[Length[{y}]],{0,\[Infinity]}],Cases[repLabel,wc[x_][y__]:>x[Length[{y}]],{0,\[Infinity]}]][[1]];Graphics[Join@@Join[tools`repLine[#,label,0,False,False,True]&/@({(#-1/2)2\[Pi]/n,2\[Pi]/n}&/@Range[n]),tools`repLine[{1.95{Cos[#1],Sin[#1]},{Cos[#1],Sin[#1]}},adjointDynkinLabel[alg],#2,False,dualQ,False]&@@@(({\[Pi]-(#-1/2)2\[Pi]/n,ordering[[#]]}&/@Range[n])),tools`diagramVertex[{Cos[#],Sin[#]},label,0.07]&/@(\[Pi]-(#-1/2)2\[Pi]/n&/@Range[n])],ImageSize->If[n==2,80,120]]];
tools`graphicalTrR[repLabel_,n_Integer,dualQ_:False]/;n>=2&&BooleanQ[dualQ]:=tools`graphicalTrR[repLabel,Range[n],dualQ];
tools`graphicalTrR[repLabel_,ordering_List,others__List,dualQ_:False]/;BooleanQ[dualQ]&&Length[ordering]>=2:=Row[tools`graphicalTrR[repLabel,#,dualQ]&/@Prepend[{others},ordering]];

(*dot-powers of representations*)
